/* Deutsch Trainer — B2 grammar band (lv:5).
   15 lessons + 120 targeted drills.
   B2 is not about building correct sentences any more — the learner can do that.
   It is about CHOOSING between several correct options and sounding native.
   Globals: window.GRAM_B2 (lessons) · window.DRILL_B2 (drills).            */

window.GRAM_B2=[

/* ================= 1 · Konjunktiv II in the past ================= */
{id:'konjunktiv2-vergangenheit',ic:'🕰️',lv:5,sk:'Konjunktiv',
 title:{en:'Past Konjunktiv II',fa:'وجه شرطی گذشته'},
 sub:{en:'hätte / wäre + Partizip II — the chance you missed',fa:'hätte / wäre + اسم مفعول'},
 blocks:[
  {type:'text',md:{en:'You already say <i>Wenn ich Zeit hätte, würde ich kommen</i> — an unreal <b>present</b>. B2 adds the tense that adults actually need: the unreal <b>past</b>. This is the grammar of regret, of blame, of near-misses and of job interviews („Rückblickend hätte ich das anders gemacht").',
        fa:'تو همین حالا <i>Wenn ich Zeit hätte…</i> را می‌سازی — شرط غیرواقعی در <b>حال</b>. حالا نوبت گذشتهٔ غیرواقعی است: زبان پشیمانی، سرزنش و فرصت‌های از‌دست‌رفته.'}},
  {type:'rule',md:{en:'There is only <b>one</b> past form, and it is built from the Perfekt: take the Perfekt, put the auxiliary into Konjunktiv II. <b>habe → hätte</b>, <b>bin → wäre</b>. The participle never changes. <b>würde + Partizip II does not exist.</b>',
        fa:'فقط <b>یک</b> فرم گذشته وجود دارد: ماضی نقلی را بگیر و فعل کمکی را به Konjunktiv II ببر. <b>habe → hätte</b>، <b>bin → wäre</b>. <b>würde + اسم مفعول وجود ندارد.</b>'}},
  {type:'table',head:['Perfekt (it happened)','Konjunktiv II Vergangenheit','English'],
   rows:[['ich habe gelernt','*ich hätte gelernt','I would have studied'],
         ['ich bin geblieben','*ich wäre geblieben','I would have stayed'],
         ['sie hat gekündigt','*sie hätte gekündigt','she would have resigned'],
         ['es ist passiert','*es wäre passiert','it would have happened'],
         ['wir haben arbeiten müssen','*wir hätten arbeiten müssen','we would have had to work']],
   cap:{en:'the auxiliary carries the whole tense',fa:'فعل کمکی تمام بار زمان را می‌برد'}},
  {type:'examples',items:[
   {de:'Wenn ich das gewusst hätte, hätte ich nichts gesagt.',en:'If I had known that, I would not have said anything.',say:'Wenn ich das gewusst hätte, hätte ich nichts gesagt.'},
   {de:'Mit einem früheren Zug wäre ich pünktlich angekommen.',en:'With an earlier train I would have arrived on time.',say:'Mit einem früheren Zug wäre ich pünktlich angekommen.'},
   {de:'Fast hätte ich die Frist verpasst.',en:'I almost missed the deadline.',say:'Fast hätte ich die Frist verpasst.'},
   {de:'Hätte ich doch den Vertrag genauer gelesen!',en:'If only I had read the contract more carefully!',say:'Hätte ich doch den Vertrag genauer gelesen!'},
   {de:'An deiner Stelle hätte ich sofort widersprochen.',en:'In your position I would have objected immediately.',say:'An deiner Stelle hätte ich sofort widersprochen.'}]},
  {type:'contrast',cols:[
   {t:'Unreal now / later',md:{en:'<b>hätte / wäre / würde + Infinitiv</b><br>„Wenn ich mehr Zeit <b>hätte</b>, <b>würde</b> ich den Kurs machen."<br>The door is still open — I could still do it.'}},
   {t:'Unreal in the past',md:{en:'<b>hätte / wäre + Partizip II</b><br>„Wenn ich mehr Zeit <b>gehabt hätte</b>, <b>hätte</b> ich den Kurs <b>gemacht</b>."<br>The door is shut — it never happened.'}}]},
  {type:'text',md:{en:'Two small words turn the form into fluent speech. <b>fast / beinahe</b> + past Konjunktiv II = „it very nearly happened": <i>Beinahe hätten wir den Auftrag verloren.</i> And <b>doch / nur</b> in a verb-first clause = a bare wish: <i>Hätte ich doch früher gefragt!</i><br>And with a <b>modal verb</b> you get the double infinitive — the auxiliary is then <b>always hätte</b>, even for verbs that normally take <i>sein</i>: <i>Ich <b>hätte</b> früher <b>gehen müssen</b>.</i> Word order: hätte … Vollverb-Infinitiv … Modal-Infinitiv.',
        fa:'دو کلمهٔ کوچک این فرم را طبیعی می‌کند: <b>fast / beinahe</b> = «نزدیک بود»، و <b>doch / nur</b> در جملهٔ فعل‌اول = آرزوی خالص.<br>با فعل مُدال، مصدر دوگانه می‌آید و فعل کمکی <b>همیشه hätte</b> است، حتی برای فعل‌هایی که معمولاً sein می‌گیرند.'}},
  {type:'examples',items:[
   {de:'Du hättest mich anrufen können.',en:'You could have called me.',say:'Du hättest mich anrufen können.'},
   {de:'Das hätte nicht passieren dürfen.',en:'That should not have been allowed to happen.',say:'Das hätte nicht passieren dürfen.'},
   {de:'Ich hätte gestern länger bleiben müssen.',en:'I would have had to stay longer yesterday.',say:'Ich hätte gestern länger bleiben müssen.'},
   {de:'Er ärgert sich, dass er die Stelle hätte bekommen können.',en:'He is annoyed that he could have got the job.',say:'Er ärgert sich, dass er die Stelle hätte bekommen können.'}]},
  {type:'warn',md:{en:'Three traps, all of them over-applications of B1 habits. <b>1)</b> <i>Ich würde gegangen sein</i> ✗ — there is no <i>würde</i> in the past; say <b>ich wäre gegangen</b>. <b>2)</b> <i>Ich hätte gegangen</i> ✗ — a verb that takes <i>sein</i> in the Perfekt keeps <i>sein</i>: <b>wäre gegangen</b>. <b>3)</b> <i>Ich hätte kommen gekonnt</i> ✗ — a modal with a second verb never appears as a participle: <b>hätte kommen können</b>.',
        fa:'سه دام: <i>würde gegangen sein</i> ✗ → <b>wäre gegangen</b>؛ <i>hätte gegangen</i> ✗ → <b>wäre gegangen</b>؛ <i>hätte kommen gekonnt</i> ✗ → <b>hätte kommen können</b>.'}},
  {type:'tip',md:{en:'In a subordinate clause the auxiliary jumps <b>in front of</b> the double infinitive: „…, weil ich <b>hätte</b> arbeiten <b>müssen</b>." Everywhere else German sends the finite verb to the end — this is the one family of exceptions.',
        fa:'در جملهٔ پیرو، فعل کمکی <b>پیش از</b> مصدر دوگانه می‌آید: «…, weil ich <b>hätte</b> arbeiten <b>müssen</b>.»'}},
  {type:'quiz',q:{en:'Complete: „Wenn ich von der Sitzung gewusst hätte, …"'},
   a:'wäre ich nicht nach Hause gefahren',
   o:['würde ich nicht nach Hause gefahren sein','hätte ich nicht nach Hause gefahren','wäre ich nicht nach Hause fahren'],
   ex:{en:'<i>fahren</i> takes <b>sein</b> in the Perfekt (ich bin gefahren), so the unreal past is <b>wäre … gefahren</b>. No <i>würde</i>, and the participle stays <i>gefahren</i>.'}}
 ]},

/* ================= 2 · Unreal comparisons ================= */
{id:'irreale-vergleiche',ic:'🪞',lv:5,sk:'Konjunktiv',
 title:{en:'als ob, als wenn, als',fa:'مقایسهٔ غیرواقعی'},
 sub:{en:'Comparing with something that is not true',fa:'مقایسه با چیزی که واقعی نیست'},
 blocks:[
  {type:'text',md:{en:'German has a whole structure for „he acts <i>as if</i>…" — a comparison with a situation that does not exist. You meet it constantly in commentary, reviews and office gossip, and it is one of the fastest ways to sound advanced.',
        fa:'آلمانی ساختاری کامل برای «چنان رفتار می‌کند که گویی…» دارد — مقایسه با وضعیتی که وجود ندارد.'}},
  {type:'rule',md:{en:'<b>als ob</b> and <b>als wenn</b> are subordinators: the verb goes to the <b>end</b>. You may drop <b>ob/wenn</b> — then only <b>als</b> is left and the finite verb moves up <b>immediately after als</b>. The verb stands in <b>Konjunktiv II</b>.',
        fa:'<b>als ob</b> و <b>als wenn</b> فعل را به <b>آخر</b> می‌فرستند. اگر ob/wenn را حذف کنی، فعل صرف‌شده <b>بی‌درنگ بعد از als</b> می‌آید. فعل در Konjunktiv II است.'}},
  {type:'table',head:['Form','Position of the verb','Example'],
   rows:[['als ob','last','*Er tut so, als ob er alles wüsste.'],
         ['als wenn','last (more spoken)','*Du redest, als wenn du der Chef wärst.'],
         ['als','straight after <i>als</i>','*Er tut so, als wüsste er alles.'],
         ['als (+ past)','hätte / wäre + Partizip II','*Sie erzählt davon, als hätte sie es erfunden.']],
   cap:{en:'same meaning, three registers',fa:'یک معنا، سه سطح زبانی'}},
  {type:'examples',items:[
   {de:'Er tut so, als wüsste er alles.',en:'He acts as if he knew everything.',say:'Er tut so, als wüsste er alles.'},
   {de:'Sie sprach über das Projekt, als ob sie es selbst geleitet hätte.',en:'She talked about the project as if she had run it herself.',say:'Sie sprach über das Projekt, als ob sie es selbst geleitet hätte.'},
   {de:'Nach der Kritik arbeitete er weiter, als wäre nichts geschehen.',en:'After the criticism he carried on working as if nothing had happened.',say:'Nach der Kritik arbeitete er weiter, als wäre nichts geschehen.'},
   {de:'Es sieht so aus, als würden die Verhandlungen scheitern.',en:'It looks as if the negotiations are going to fail.',say:'Es sieht so aus, als würden die Verhandlungen scheitern.'},
   {de:'Mir ist, als hätte ich diesen Namen schon gehört.',en:'I have the feeling I have heard that name before.',say:'Mir ist, als hätte ich diesen Namen schon gehört.'}]},
  {type:'contrast',cols:[
   {t:'als ob + verb LAST',md:{en:'„Sie verhält sich, <b>als ob</b> sie die Abteilung <b>leiten würde</b>."<br>Normal subordinate clause. Neutral, safe, usable in writing and speech.'}},
   {t:'als + verb SECOND slot',md:{en:'„Sie verhält sich, <b>als leitete</b> sie die Abteilung."<br>Same meaning, tighter and more literary. The finite verb must sit directly behind <i>als</i> — nothing may come between.'}}]},
  {type:'text',md:{en:'The structure has three favourite host phrases, worth learning as blocks: <b>tun, als ob</b> = to pretend; <b>Es sieht so aus, als ob</b> = it looks as if; <b>Mir ist, als ob</b> = I have the feeling that. Note the <b>so</b> in <i>tun so</i> and <i>sieht so aus</i> — it is the little anchor the comparison hangs on.',
        fa:'سه عبارت میزبان: <b>tun, als ob</b> (ادا درآوردن)، <b>Es sieht so aus, als ob</b>، <b>Mir ist, als ob</b>. به <b>so</b> دقت کن.'}},
  {type:'dialog',lines:[
   {who:'A',de:'Hat Jonas die Zahlen eigentlich selbst gerechnet?',en:'Did Jonas actually do the figures himself?'},
   {who:'B',de:'Nein — aber er präsentiert sie, als hätte er drei Nächte daran gesessen.',en:'No — but he presents them as if he had spent three nights on them.'},
   {who:'A',de:'Typisch. Er tut immer so, als ob er allein die Abteilung tragen würde.',en:'Typical. He always acts as if he were carrying the department on his own.'},
   {who:'B',de:'Und keiner widerspricht, als wäre das völlig normal.',en:'And nobody objects, as if that were completely normal.'}]},
  {type:'warn',md:{en:'The English-driven error is <b>wie</b>: <i>Er redet, wie er alles weiß</i> ✗. German never uses <i>wie</i> for an unreal comparison — only <b>als ob / als wenn / als</b>. The second error is mixing the two word orders: <i>Er tut so, als er alles wüsste</i> ✗. Once <b>ob</b> is gone, the verb must come first: <b>als wüsste er alles</b>.',
        fa:'خطای رایج زیر تأثیر انگلیسی: <b>wie</b> ✗. آلمانی برای مقایسهٔ غیرواقعی فقط <b>als ob / als wenn / als</b> دارد. خطای دوم: ترکیب دو ترتیب — بعد از حذف ob، فعل باید اول بیاید.'}},
  {type:'tip',md:{en:'In speech you will hear <b>als ob + Indikativ</b> („als ob er alles weiß"). It is common but marked as casual; in any exam, letter or report keep the Konjunktiv II. And the bare <b>„Als ob!"</b> on its own means „Yeah, right!"',
        fa:'در گفتار <b>als ob + اخباری</b> هم شنیده می‌شود، اما در آزمون و نوشتار Konjunktiv II را نگه دار. <b>«Als ob!»</b> تنها یعنی «آره، حتماً!»'}},
  {type:'quiz',q:{en:'Which sentence is correct?'},
   a:'Er verhält sich, als hätte er den Auftrag schon.',
   o:['Er verhält sich, als er den Auftrag schon hätte.','Er verhält sich, wie er den Auftrag schon hat.','Er verhält sich, als ob er den Auftrag schon hätte gehabt.'],
   ex:{en:'Without <b>ob</b> the finite verb follows <i>als</i> directly: <b>als hätte er</b>…. <i>wie</i> is impossible here, and <i>hätte gehabt</i> doubles the past.'}}
 ]},

/* ================= 3 · The passive across all tenses ================= */
{id:'passiv-zeiten',ic:'🔁',lv:5,sk:'Passive',
 title:{en:'The passive in every tense',fa:'مجهول در همهٔ زمان‌ها'},
 sub:{en:'wird · wurde · ist … worden · muss … werden',fa:'wird · wurde · ist … worden'},
 blocks:[
  {type:'text',md:{en:'At B1 you learned <i>wird gebaut</i> and <i>wurde gebaut</i>. Those two cover maybe 70% of real passives — but official German, minutes of meetings, laws and news reports need the whole set, and the Perfekt in particular, because that is the tense people speak in.',
        fa:'در B1 فقط <i>wird gebaut</i> و <i>wurde gebaut</i> را یاد گرفتی. آلمانی اداری، خبری و حقوقی به همهٔ زمان‌ها نیاز دارد — بخصوص ماضی نقلی.'}},
  {type:'table',head:['Tense','Pattern','Example'],
   rows:[['Präsens','wird + Partizip II','*Der Antrag wird geprüft.'],
         ['Präteritum','wurde + Partizip II','*Der Antrag wurde geprüft.'],
         ['Perfekt','ist + Partizip II + <b>worden</b>','*Der Antrag ist geprüft worden.'],
         ['Plusquamperfekt','war + Partizip II + <b>worden</b>','*Der Antrag war geprüft worden.'],
         ['Futur I','wird + Partizip II + werden','*Der Antrag wird geprüft werden.'],
         ['Futur II','wird + Partizip II + worden sein','*Der Antrag wird geprüft worden sein.']],
   cap:{en:'the passive always ends on a form of werden',fa:'مجهول همیشه به شکلی از werden ختم می‌شود'}},
  {type:'rule',md:{en:'In the passive, the participle of <i>werden</i> loses its <b>ge-</b>: <b>worden</b>, not <i>geworden</i>. And the Perfekt auxiliary is <b>sein</b>, never <i>haben</i>: <b>ist geprüft worden</b>. Keep <i>geworden</i> for the full verb <i>werden</i> = „to become": <i>Er ist Lehrer geworden.</i><br>With a <b>modal verb</b> the passive infinitive <b>Partizip II + werden</b> goes to the end: <i>Der Vertrag <b>muss</b> heute <b>unterschrieben werden</b>.</i> In the past prefer the Präteritum of the modal (<i>musste unterschrieben werden</i>); the full Perfekt (<i>hat unterschrieben werden müssen</i>) is correct but heavy, and the form you really need is the Konjunktiv one: <i>hätte unterschrieben werden müssen</i>.',
        fa:'در مجهول، اسم مفعول <i>werden</i> بدون <b>ge-</b> می‌آید: <b>worden</b>. فعل کمکی <b>sein</b> است. <i>geworden</i> فقط برای werden به معنای «شدن».<br>با فعل مُدال، مصدر مجهول <b>اسم مفعول + werden</b> به آخر می‌رود؛ در گذشته Präteritum مُدال را ترجیح بده.'}},
  {type:'examples',items:[
   {de:'Die Verträge sind letzte Woche unterschrieben worden.',en:'The contracts were signed last week.',say:'Die Verträge sind letzte Woche unterschrieben worden.'},
   {de:'Das Gebäude war bereits 2019 verkauft worden.',en:'The building had already been sold in 2019.',say:'Das Gebäude war bereits 2019 verkauft worden.'},
   {de:'Die Ergebnisse werden morgen veröffentlicht.',en:'The results will be published tomorrow.',say:'Die Ergebnisse werden morgen veröffentlicht.'},
   {de:'Bis Freitag wird die Entscheidung getroffen worden sein.',en:'By Friday the decision will have been taken.',say:'Bis Freitag wird die Entscheidung getroffen worden sein.'},
   {de:'Er ist zum Abteilungsleiter befördert worden.',en:'He has been promoted to head of department.',say:'Er ist zum Abteilungsleiter befördert worden.'}]},
  {type:'rule',md:{en:'German can form a passive with <b>no subject at all</b>. A Dative object stays in the Dative — it never becomes the subject the way English makes „I was helped". The front slot is then filled by something else, or by a placeholder <b>es</b>.',
        fa:'آلمانی می‌تواند مجهول <b>بدون فاعل</b> بسازد. مفعول داتیو داتیو می‌ماند و هرگز فاعل نمی‌شود. جایگاه اول را عنصر دیگری یا <b>es</b> پر می‌کند.'}},
  {type:'examples',items:[
   {de:'Mir wurde bei der Bewerbung sehr geholfen.',en:'I was given a lot of help with the application.',say:'Mir wurde bei der Bewerbung sehr geholfen.'},
   {de:'Den Mitarbeitern wurde fristgerecht gekündigt.',en:'The employees were given notice on time.',say:'Den Mitarbeitern wurde fristgerecht gekündigt.'},
   {de:'Es wird hier nicht geraucht.',en:'There is no smoking here.',say:'Es wird hier nicht geraucht.'},
   {de:'In der Werkstatt wird bis 18 Uhr gearbeitet.',en:'Work goes on in the workshop until 6 p.m.',say:'In der Werkstatt wird bis 18 Uhr gearbeitet.'}]},
  {type:'contrast',cols:[
   {t:'Vorgangspassiv — werden',md:{en:'„Die Tür <b>wird</b> um 20 Uhr <b>geschlossen</b>."<br>An <b>action</b> happening to the door. Answers <i>what is being done?</i>'}},
   {t:'Zustandspassiv — sein',md:{en:'„Die Tür <b>ist</b> <b>geschlossen</b>."<br>The <b>result</b>, a state. Answers <i>how are things?</i> Perfekt of this one: <b>ist geschlossen gewesen</b>.'}}]},
  {type:'warn',md:{en:'The two B2 killers. <b>1)</b> <i>Ich werde geholfen</i> ✗. <i>helfen</i> takes the Dative, so the only passive is <b>Mir wird geholfen</b> — same for <i>danken, gratulieren, kündigen, zuhören, antworten</i>. <b>2)</b> <i>Der Antrag ist geprüft geworden</i> ✗ — in a passive it is always <b>worden</b>.',
        fa:'دو خطای کشنده: <i>Ich werde geholfen</i> ✗ → <b>Mir wird geholfen</b>؛ و <i>geprüft geworden</i> ✗ → <b>geprüft worden</b>.'}},
  {type:'tip',md:{en:'Reading trick for long official sentences: find the <b>last two words</b> first. <i>…worden</i> → Perfekt passive. <i>…werden müssen</i> → modal passive. <i>…worden sein</i> → Futur II passive. The end of the sentence tells you the tense before you have understood a single noun.',
        fa:'ترفند خواندن: ابتدا <b>دو کلمهٔ آخر</b> را پیدا کن — آخر جمله زمان را لو می‌دهد.'}},
  {type:'quiz',q:{en:'„Die Unterlagen ___ vollständig geprüft ___." — which pair fits?'},
   a:'sind … worden',o:['haben … worden','sind … geworden','wurden … worden'],
   ex:{en:'Perfekt passive = <b>sein</b> + Partizip II + <b>worden</b>. <i>haben</i> is wrong, <i>geworden</i> belongs to „become", and <i>wurden … worden</i> doubles the tense.'}}
 ]},

/* ================= 4 · Advanced infinitive clauses ================= */
{id:'infinitiv-advanced',ic:'➡️',lv:5,sk:'Clauses',
 title:{en:'ohne … zu, anstatt … zu, außer zu',fa:'ohne … zu و anstatt … zu'},
 sub:{en:'And when you must switch to ohne dass',fa:'و چه وقت باید ohne dass گفت'},
 blocks:[
  {type:'text',md:{en:'<b>um … zu</b> you know. Its two siblings are just as frequent in adult German and much rarer in learner German, which is exactly why they pay off: <b>ohne … zu</b> (without doing) and <b>anstatt … zu</b> (instead of doing).',
        fa:'<b>um … zu</b> را می‌شناسی. دو خواهر پرکاربردش: <b>ohne … zu</b> و <b>anstatt … zu</b>.'}},
  {type:'rule',md:{en:'The <b>subject rule</b> decides the form. One single subject for both actions → infinitive with <b>zu</b> and no subject in the clause. Two different subjects → you <b>must</b> switch to <b>ohne dass</b> / <b>anstatt dass</b> with a full clause and a verb at the end.',
        fa:'قاعدهٔ فاعل: یک فاعل برای هر دو کار → مصدر با <b>zu</b>؛ دو فاعل متفاوت → باید به <b>ohne dass</b> / <b>anstatt dass</b> با جملهٔ کامل بروی.'}},
  {type:'table',head:['Subjects','Form','Example'],
   rows:[['same','ohne … zu','*Er ging, ohne sich zu verabschieden.'],
         ['different','ohne dass','*Er ging, ohne dass es jemand merkte.'],
         ['same','anstatt … zu','*Anstatt zu telefonieren, schrieb sie eine E-Mail.'],
         ['different','anstatt dass','*Anstatt dass die Firma die Löhne erhöhte, kürzte sie die Stunden.'],
         ['same','außer zu','*Uns bleibt nichts, außer zu warten.']],
   cap:{en:'the subject decides, not the meaning',fa:'فاعل تعیین می‌کند، نه معنا'}},
  {type:'examples',items:[
   {de:'Sie unterschrieb den Vertrag, ohne ihn gelesen zu haben.',en:'She signed the contract without having read it.',say:'Sie unterschrieb den Vertrag, ohne ihn gelesen zu haben.'},
   {de:'Er verließ die Sitzung, ohne ein Wort zu sagen.',en:'He left the meeting without saying a word.',say:'Er verließ die Sitzung, ohne ein Wort zu sagen.'},
   {de:'Anstatt sich zu beschweren, sollten Sie einen Antrag stellen.',en:'Instead of complaining you should file an application.',say:'Anstatt sich zu beschweren, sollten Sie einen Antrag stellen.'},
   {de:'Ohne dass wir informiert wurden, wurde der Termin verschoben.',en:'The appointment was moved without our being informed.',say:'Ohne dass wir informiert wurden, wurde der Termin verschoben.'},
   {de:'Er reiste ab, ohne sich vorher anzumelden.',en:'He left without registering beforehand.',say:'Er reiste ab, ohne sich vorher anzumelden.'}]},
  {type:'contrast',cols:[
   {t:'ohne … zu',md:{en:'„Ich habe gekündigt, <b>ohne</b> einen neuen Job <b>zu haben</b>."<br>I did the leaving and I am the one without the job — <b>one</b> subject, so no subject is written.'}},
   {t:'ohne dass',md:{en:'„Ich habe gekündigt, <b>ohne dass</b> mein Chef <b>überrascht war</b>."<br>Second actor appears (<i>mein Chef</i>) → a full clause is obligatory, verb at the end.'}}]},
  {type:'steps',items:[
   {en:'Name the two actions and ask: who does each one?',fa:'دو کار را نام ببر و بپرس هر کدام را چه کسی انجام می‌دهد؟'},
   {en:'Same person → write <i>ohne / anstatt</i> + the rest + <b>zu</b> + Infinitiv at the end.',fa:'یک نفر → <i>ohne / anstatt</i> + … + <b>zu</b> + مصدر.'},
   {en:'Separable verb → <b>zu</b> goes inside: an<b>zu</b>melden, mit<b>zu</b>teilen.',fa:'فعل جداشدنی → <b>zu</b> داخل فعل می‌رود.'},
   {en:'Already finished before the main action? Use <b>Partizip II + zu haben / zu sein</b>: <i>ohne gefragt zu haben</i>.',fa:'اگر پیش‌تر تمام شده → <b>اسم مفعول + zu haben / zu sein</b>.'},
   {en:'Different person → rewrite with <i>ohne dass</i> / <i>anstatt dass</i> and a finite verb at the end.',fa:'شخص متفاوت → با <i>ohne dass</i> / <i>anstatt dass</i> بازنویسی کن.'}]},
  {type:'text',md:{en:'<b>außer zu</b> is the small one worth collecting. It appears after a negative or a „nothing but" phrase: <i>Es blieb uns nichts übrig, <b>außer zu</b> warten.</i> With a different subject it becomes <b>außer dass</b>: <i>Ich weiß nichts, <b>außer dass</b> der Termin platzt.</i>',
        fa:'<b>außer zu</b> بعد از عبارت منفی می‌آید؛ با فاعل متفاوت <b>außer dass</b> می‌شود.'}},
  {type:'warn',md:{en:'Two errors. <b>1)</b> English „without knowing" has no <i>to</i>, so learners write <i>ohne wissen</i> ✗ — German always needs <b>zu</b>: <b>ohne zu wissen</b>. <b>2)</b> The subject rule gets ignored: <i>ohne dass ich zu fragen</i> ✗ and <i>ohne mein Chef zu wissen</i> ✗. Pick <b>one</b> of the two constructions; never mix a subject into the zu-clause.',
        fa:'دو خطا: <i>ohne wissen</i> ✗ (همیشه <b>zu</b> لازم است)؛ و گذاشتن فاعل داخل بند مصدری ✗.'}},
  {type:'tip',md:{en:'A negative <i>ohne … zu</i> clause often translates an English „-ing" that a learner would render with <i>und nicht</i>: not „Er ging und sagte nichts" but <b>„Er ging, ohne etwas zu sagen."</b> Swapping <i>und nicht</i> for <i>ohne … zu</i> instantly raises the register of a whole text.',
        fa:'جایگزینی <i>und nicht</i> با <i>ohne … zu</i> فوراً سطح متن را بالا می‌برد.'}},
  {type:'quiz',q:{en:'„___ der Kunde zugestimmt hatte, wurde die Rechnung verschickt."'},
   a:'Ohne dass',o:['Ohne zu','Ohne','Anstatt zu'],
   ex:{en:'The invoice was sent by us, the agreeing was the customer\'s — two subjects, so the full clause with <b>ohne dass</b> is the only option.'}}
 ]},

/* ================= 5 · The full connector system ================= */
{id:'konnektoren-b2',ic:'🧷',lv:5,sk:'Connectors',
 title:{en:'Connectors and their positions',fa:'رابط‌ها و جایگاهشان'},
 sub:{en:'Position 0, position 1, verb last — and the middle field',fa:'جایگاه ۰، جایگاه ۱، فعل آخر'},
 blocks:[
  {type:'text',md:{en:'B2 writing is judged on connectors, and the mistakes are almost never about meaning — they are about <b>position</b>. German sorts every connector into one of four slots, and the slot decides the word order. Learn the slots, and <i>trotzdem / obwohl / denn</i> stop being a lottery.',
        fa:'در B2 خطای رابط‌ها تقریباً هرگز معنایی نیست، بلکه <b>جایگاهی</b> است. آلمانی هر رابط را در یکی از چهار جایگاه می‌گذارد و جایگاه، ترتیب کلمات را تعیین می‌کند.'}},
  {type:'table',head:['Class','Slot','Word order','Members'],
   rows:[['Konjunktion','*Position 0','subject then verb, untouched','und, aber, oder, denn, sondern'],
         ['Konjunktionaladverb','*Position 1','verb second → <b>inversion</b>','deshalb, darum, daher, trotzdem, dennoch, außerdem, stattdessen, folglich, somit, sonst'],
         ['Subjunktion','*inside the clause','finite verb <b>last</b>','weil, obwohl, damit, dass, wenn, während, indem, sodass, falls, nachdem'],
         ['Mittelfeld-fähig','*middle field','verb untouched','jedoch, allerdings, nämlich, hingegen, zwar']],
   cap:{en:'four classes, four behaviours',fa:'چهار دسته، چهار رفتار'}},
  {type:'rule',md:{en:'A <b>Konjunktion</b> sits in front of the sentence without using up the first slot: „…, <b>denn</b> ich bin müde." A <b>Konjunktionaladverb</b> <i>is</i> the first slot, so the verb must follow it: „…, <b>deshalb</b> <b>bin</b> ich müde." Test any connector by asking whether the subject or the verb comes next.',
        fa:'<b>حرف ربط</b> جایگاه اول را اشغال نمی‌کند؛ <b>قید ربطی</b> خودش جایگاه اول است، پس فعل بعد از آن می‌آید.'}},
  {type:'examples',items:[
   {de:'Er wollte kündigen, aber er hatte noch keinen neuen Job.',en:'He wanted to resign, but he did not have a new job yet.',say:'Er wollte kündigen, aber er hatte noch keinen neuen Job.'},
   {de:'Die Miete ist hoch, trotzdem bleiben wir in der Wohnung.',en:'The rent is high; we are staying in the flat anyway.',say:'Die Miete ist hoch, trotzdem bleiben wir in der Wohnung.'},
   {de:'Wir haben den Termin verschoben, weil der Kunde krank war.',en:'We moved the appointment because the client was ill.',say:'Wir haben den Termin verschoben, weil der Kunde krank war.'},
   {de:'Ich nehme das Angebot an, denn es ist das beste.',en:'I am accepting the offer, because it is the best one.',say:'Ich nehme das Angebot an, denn es ist das beste.'},
   {de:'Die Zahlen sind gut; das Risiko ist allerdings erheblich.',en:'The figures are good; the risk, however, is considerable.',say:'Die Zahlen sind gut; das Risiko ist allerdings erheblich.'}]},
  {type:'contrast',cols:[
   {t:'weil — Subjunktion',md:{en:'„Ich bleibe zu Hause, <b>weil</b> ich krank <b>bin</b>."<br>Verb to the end. Can also open the sentence: „<b>Weil</b> ich krank bin, bleibe ich zu Hause."'}},
   {t:'denn — Konjunktion',md:{en:'„Ich bleibe zu Hause, <b>denn</b> ich <b>bin</b> krank."<br>Normal main-clause order. Can <b>never</b> open a sentence and never takes a verb to the end.'}}]},
  {type:'text',md:{en:'The <b>middle field</b> (<i>Mittelfeld</i>) is everything between the finite verb and the end of the sentence. A handful of connectors can move in there, which is a stylistic luxury: <i>Das Risiko ist <b>allerdings</b> erheblich</i> / <i><b>Allerdings</b> ist das Risiko erheblich</i>. Both correct; the inner position sounds calmer and more written.',
        fa:'<b>Mittelfeld</b> یعنی فاصلهٔ میان فعل صرف‌شده و پایان جمله. چند رابط می‌توانند آنجا بنشینند — همان جایگاه، لحن را آرام‌تر و نوشتاری‌تر می‌کند.'}},
  {type:'steps',items:[
   {en:'Decide the relation: cause, contrast, consequence, purpose.',fa:'رابطه را تعیین کن: علت، تضاد، نتیجه، هدف.'},
   {en:'Pick the connector — then look up its class.',fa:'رابط را انتخاب کن، بعد دستهٔ آن را ببین.'},
   {en:'Position 0 → change nothing. Position 1 → invert. Subjunktion → verb last.',fa:'جایگاه ۰ → تغییری نده. جایگاه ۱ → معکوس کن. Subjunktion → فعل آخر.'},
   {en:'Read the clause back and check which word stands directly after the connector.',fa:'بند را بخوان و ببین کدام کلمه مستقیماً بعد از رابط آمده است.'}]},
  {type:'warn',md:{en:'<b>trotzdem</b> is the classic. It is an <b>adverb</b>, not a subordinator: <i>trotzdem er krank war</i> ✗ → <b>obwohl</b> er krank war, or „Er war krank; <b>trotzdem</b> kam er." The mirror error is inverting after <b>denn</b> or <b>aber</b>: <i>denn bin ich müde</i> ✗. And <b>weil</b> with main-clause order (<i>weil ich bin müde</i>) is spoken German only — never write it.',
        fa:'<b>trotzdem</b> قید است نه حرف ربط پیرو‌ساز: <i>trotzdem er krank war</i> ✗ → <b>obwohl</b>. و معکوس‌سازی بعد از <b>denn/aber</b> ✗.'}},
  {type:'tip',md:{en:'Pairs worth memorising as whole sentences, because exams test them in both directions: <b>weil ↔ deshalb</b>, <b>obwohl ↔ trotzdem</b>, <b>damit ↔ dafür</b>, <b>sodass ↔ folglich</b>. One subordinator, one adverb, same meaning, opposite word order.',
        fa:'جفت‌ها را به‌صورت جملهٔ کامل حفظ کن: <b>weil ↔ deshalb</b>، <b>obwohl ↔ trotzdem</b>، <b>damit ↔ dafür</b>.'}},
  {type:'quiz',q:{en:'„Das Projekt war teuer, ___ hat es sich gelohnt."'},
   a:'dennoch',o:['obwohl','denn','trotz'],
   ex:{en:'The verb <i>hat</i> comes straight after the gap, so slot 1 must be filled by a <b>Konjunktionaladverb</b>: <b>dennoch</b>. <i>obwohl</i> would need the verb at the end, <i>denn</i> would need the subject next, <i>trotz</i> needs a noun.'}}
 ]},

/* ================= 6 · Prepositional objects ================= */
{id:'praepositional-objekt',ic:'🪄',lv:5,sk:'Prepositions',
 title:{en:'Prepositional objects in depth',fa:'مفعول با حرف اضافه'},
 sub:{en:'da-/wo-, „darauf, dass …", and prepositions that change the meaning',fa:'نظام da-/wo- و حروف اضافه‌ای که معنا را عوض می‌کنند'},
 blocks:[
  {type:'text',md:{en:'Many German verbs come welded to a preposition: <i>warten <b>auf</b></i>, <i>sich erinnern <b>an</b></i>, <i>bestehen <b>aus</b></i>. The technical name for this fixed demand is <b>Rektion</b> — the verb <i>governs</i> a preposition and a case, and you cannot reason your way to them from the meaning. They are part of the word, like gender.',
        fa:'بسیاری از فعل‌های آلمانی به یک حرف اضافه چسبیده‌اند. نام فنی این الزام <b>Rektion</b> است: فعل حرف اضافه و حالت را «حکم» می‌کند؛ از معنا قابل استنتاج نیست، مثل جنس اسم.'}},
  {type:'table',head:['Verb + preposition','Case','Example'],
   rows:[['warten auf','Akk','*Ich warte auf eine Antwort.'],
         ['sich erinnern an','Akk','*Erinnerst du dich an den Termin?'],
         ['sich beschäftigen mit','Dat','*Die Studie beschäftigt sich mit Mieten.'],
         ['abhängen von','Dat','*Alles hängt von der Finanzierung ab.'],
         ['rechnen mit','Dat','*Wir rechnen mit höheren Kosten.'],
         ['beharren auf','Dat','*Die Gewerkschaft beharrt auf einer Zusage.'],
         ['sich bewerben um','Akk','*Sie bewirbt sich um die Stelle.'],
         ['teilnehmen an','Dat','*Er nimmt an der Schulung teil.']],
   cap:{en:'learn the three-part block: verb + preposition + case',fa:'بلوک سه‌جزئی را یاد بگیر: فعل + حرف اضافه + حالت'}},
  {type:'rule',md:{en:'Replacing the object: <b>things</b> → <b>da(r)-</b> + preposition (<i>darauf, damit, davon, daran</i>); <b>questions about things</b> → <b>wo(r)-</b> (<i>worauf, womit, wovon, woran</i>). The <b>-r-</b> appears only before a vowel: da<b>r</b>auf but da<b>mit</b>. <b>People</b> keep the preposition and take a normal pronoun: <i>auf ihn, mit ihr, an wen?</i>',
        fa:'برای <b>چیزها</b>: <b>da(r)-</b> + حرف اضافه؛ برای <b>پرسش از چیزها</b>: <b>wo(r)-</b>. حرف <b>r</b> فقط پیش از مصوت می‌آید. برای <b>اشخاص</b> حرف اضافه + ضمیر معمولی.'}},
  {type:'examples',items:[
   {de:'Ich kann mich daran nicht erinnern.',en:'I cannot remember that.',say:'Ich kann mich daran nicht erinnern.'},
   {de:'Womit beschäftigt sich die Studie?',en:'What does the study deal with?',say:'Womit beschäftigt sich die Studie?'},
   {de:'Auf wen wartet ihr noch?',en:'Who are you still waiting for?',say:'Auf wen wartet ihr noch?'},
   {de:'Mit solchen Reaktionen hatten wir nicht gerechnet.',en:'We had not reckoned with reactions like that.',say:'Mit solchen Reaktionen hatten wir nicht gerechnet.'},
   {de:'Worüber haben Sie sich beschwert?',en:'What did you complain about?',say:'Worüber haben Sie sich beschwert?'}]},
  {type:'rule',md:{en:'The real B2 move: <b>da-</b> can point <b>forward</b> to a whole clause. The verb keeps its preposition, the preposition turns into <i>da(r)-</i>, and the content follows as a <b>dass</b>-clause or a <b>zu</b>-infinitive: „Alles hängt <b>davon</b> ab, <b>ob</b> die Finanzierung steht." „Wir müssen <b>damit</b> rechnen, <b>dass</b> die Kosten steigen." „Ich freue mich <b>darauf</b>, Sie kennenzulernen."',
        fa:'حرکت اصلی B2: <b>da-</b> می‌تواند به <b>جلو</b>، به یک بند کامل، اشاره کند: فعل حرف اضافه‌اش را نگه می‌دارد، حرف اضافه <i>da(r)-</i> می‌شود و محتوا با <b>dass</b> یا مصدر <b>zu</b> می‌آید.'}},
  {type:'examples',items:[
   {de:'Wir bestehen darauf, dass die Frist eingehalten wird.',en:'We insist that the deadline be met.',say:'Wir bestehen darauf, dass die Frist eingehalten wird.'},
   {de:'Es hängt davon ab, wie die Behörde entscheidet.',en:'It depends on how the authority decides.',say:'Es hängt davon ab, wie die Behörde entscheidet.'},
   {de:'Sie hat sich dagegen entschieden, den Vertrag zu verlängern.',en:'She decided against extending the contract.',say:'Sie hat sich dagegen entschieden, den Vertrag zu verlängern.'},
   {de:'Ich zweifle daran, dass das rechtzeitig fertig wird.',en:'I doubt that it will be finished in time.',say:'Ich zweifle daran, dass das rechtzeitig fertig wird.'}]},
  {type:'contrast',cols:[
   {t:'sich freuen auf + Akk',md:{en:'„Ich freue mich <b>auf</b> den Urlaub."<br>Something <b>still ahead</b> — looking forward to it.'}},
   {t:'sich freuen über + Akk',md:{en:'„Ich freue mich <b>über</b> das Lob."<br>Something that <b>has happened</b> — pleased about it. Same verb, different time axis.'}}]},
  {type:'table',head:['Verb','Preposition','Meaning it creates'],
   rows:[['bestehen','*auf + Dat','to insist on'],
         ['bestehen','*aus + Dat','to consist of'],
         ['bestehen','*in + Dat','to lie in, to consist in (abstract)'],
         ['sich freuen','*auf + Akk','to look forward to'],
         ['sich freuen','*über + Akk','to be pleased about'],
         ['halten','*von + Dat','to have an opinion of'],
         ['halten','*für + Akk','to consider something to be'],
         ['sich handeln','*um + Akk','to be a matter of']],
   cap:{en:'the preposition is not decoration — it is the meaning',fa:'حرف اضافه تزئینی نیست؛ خودِ معناست'}},
  {type:'warn',md:{en:'Never translate the English preposition. „wait <b>for</b>" → <b>warten auf</b> (not <i>für</i>); „interested <b>in</b>" → <b>interessiert an</b> (not <i>in</i>); „depend <b>on</b>" → <b>abhängen von</b> (not <i>auf</i>); „ask <b>for</b>" → <b>bitten um</b>. And a da-form never refers to a person: <i>Ich warte darauf</i> can only mean „I am waiting for <b>it</b>" — for a person you need <b>auf ihn / auf sie</b>.',
        fa:'هرگز حرف اضافهٔ انگلیسی را ترجمه نکن: <b>warten auf</b>، <b>interessiert an</b>، <b>abhängen von</b>، <b>bitten um</b>. و فرم da- هرگز به شخص اشاره نمی‌کند.'}},
  {type:'quiz',q:{en:'„Die Gewerkschaft beharrt ___, dass die Löhne steigen."'},
   a:'darauf',o:['davon','daran','dazu'],
   ex:{en:'<i>beharren</i> governs <b>auf</b>, so the forward-pointing correlate is <b>darauf</b>. The da-form always mirrors the verb\'s own preposition — look up the verb, not the meaning.'}}
 ]},

/* ================= 7 · Word order for emphasis ================= */
{id:'wortstellung-fokus',ic:'🎯',lv:5,sk:'Sentences',
 title:{en:'Word order as a tool',fa:'ترتیب کلمات به‌عنوان ابزار'},
 sub:{en:'Vorfeld · TeKaMoLo · Ausklammerung',fa:'جایگاه اول، TeKaMoLo، برون‌گذاری'},
 blocks:[
  {type:'text',md:{en:'German word order is not free, but it is <b>flexible</b>, and at B2 the flexibility becomes a tool. Three terms: the <b>Vorfeld</b> is the slot before the finite verb; the <b>Satzklammer</b> (verb bracket) is the finite verb plus whatever sits at the very end; the <b>Mittelfeld</b> is everything between them. All your choices happen in the Vorfeld and the Mittelfeld.',
        fa:'ترتیب کلمات آلمانی آزاد نیست، اما <b>انعطاف‌پذیر</b> است. سه اصطلاح: <b>Vorfeld</b> (پیش از فعل صرف‌شده)، <b>Satzklammer</b> (قوس فعلی)، <b>Mittelfeld</b> (میان آن دو).'}},
  {type:'rule',md:{en:'The Vorfeld holds <b>exactly one</b> element — and it is the sentence\'s link to what came before. Put there the thing the reader already has in mind: a time reference, a topic, an object taken from the previous sentence. Never put new, heavy information there.',
        fa:'Vorfeld فقط <b>یک</b> عنصر می‌گیرد و پیوند جمله با جملهٔ پیشین است: چیزی که خواننده از قبل در ذهن دارد.'}},
  {type:'examples',items:[
   {de:'Den Bericht habe ich gestern eingereicht.',en:'The report — I submitted it yesterday.',say:'Den Bericht habe ich gestern eingereicht.'},
   {de:'Letzte Woche haben wir den Antrag eingereicht.',en:'Last week we submitted the application.',say:'Letzte Woche haben wir den Antrag eingereicht.'},
   {de:'Darüber müssen wir noch sprechen.',en:'That is something we still need to talk about.',say:'Darüber müssen wir noch sprechen.'},
   {de:'Mir persönlich leuchtet das Argument nicht ein.',en:'Personally, the argument does not convince me.',say:'Mir persönlich leuchtet das Argument nicht ein.'}]},
  {type:'table',head:['Order in the Mittelfeld','Abbreviation','Example'],
   rows:[['when?','*Te — temporal','heute'],
         ['why?','*Ka — kausal','wegen des Streiks'],
         ['how?','*Mo — modal','mit dem Bus'],
         ['where to / where?','*Lo — lokal','zur Arbeit']],
   cap:{en:'TeKaMoLo: heute wegen des Streiks mit dem Bus zur Arbeit',fa:'TeKaMoLo: زمان، علت، چگونگی، مکان'}},
  {type:'rule',md:{en:'TeKaMoLo is the <b>default</b> for adverbials, not a law — move an element left to stress it. But two orders really are fixed: <b>pronouns come first in the Mittelfeld</b>, immediately after the finite verb (or after the subject), and among pronouns the order flips to <b>Akkusativ before Dativ</b>.',
        fa:'TeKaMoLo <b>حالت پیش‌فرض</b> است، نه قانون. اما دو چیز ثابت است: <b>ضمایر اول Mittelfeld</b> می‌آیند و میان ضمایر ترتیب به <b>آکوزاتیو پیش از داتیو</b> برمی‌گردد.'}},
  {type:'contrast',cols:[
   {t:'Two nouns → Dativ first',md:{en:'„Ich schicke <b>dem Kunden</b> <b>die Unterlagen</b>."<br>Person before thing — the familiar B1 order.'}},
   {t:'Two pronouns → Akkusativ first',md:{en:'„Ich schicke <b>sie</b> <b>ihm</b>."<br>And mixed: the pronoun always wins the earlier slot — „Ich schicke <b>sie</b> dem Kunden", „Ich schicke <b>ihm</b> die Unterlagen."'}}]},
  {type:'text',md:{en:'<b>Ausklammerung</b> means pushing material <b>out</b> of the bracket, to the right of the final verb. Three things do this routinely: comparisons with <b>als / wie</b>, long prepositional phrases, and lists. „Die Kosten sind stärker gestiegen <b>als erwartet</b>." „Ich habe lange gesprochen <b>mit dem Betriebsrat und der Personalabteilung</b>." It keeps the sentence breathable — the alternative buries the verb.<br>Self-check when a sentence feels clumsy: say it aloud and ask „what is the <b>last</b> word before the verb at the end?" That slot is the <b>focus position</b>, the strongest place in a German sentence. If the most important word is not there, move it — or push it out behind the bracket: „Ich habe den Vertrag nicht unterschrieben, <b>und zwar aus formalen Gründen</b>."',
        fa:'<b>Ausklammerung</b> یعنی بیرون راندن مطلب از قوس فعلی، به راست فعل آخر: مقایسه با <b>als / wie</b>، عبارت‌های طولانی با حرف اضافه، و فهرست‌ها.<br>خودآزمایی: آخرین کلمه پیش از فعل پایانی، جایگاه کانونی و قوی‌ترین نقطهٔ جمله است.'}},
  {type:'examples',items:[
   {de:'Die Mieten sind schneller gestiegen als die Löhne.',en:'Rents have risen faster than wages.',say:'Die Mieten sind schneller gestiegen als die Löhne.'},
   {de:'Wir haben uns geeinigt auf einen Kompromiss, den beide Seiten tragen können.',en:'We agreed on a compromise that both sides can support.',say:'Wir haben uns geeinigt auf einen Kompromiss, den beide Seiten tragen können.'},
   {de:'Dem Antragsteller wurden die Unterlagen bereits zugeschickt.',en:'The documents have already been sent to the applicant.',say:'Dem Antragsteller wurden die Unterlagen bereits zugeschickt.'},
   {de:'Gestern hat mich der Chef vor allen gelobt.',en:'Yesterday the boss praised me in front of everyone.',say:'Gestern hat mich der Chef vor allen gelobt.'}]},
  {type:'warn',md:{en:'The B1 rule „verb second" gets over-applied as „subject second". After a Vorfeld element, a <b>pronoun object</b> normally jumps in front of the noun subject: „Gestern hat <b>mich der Chef</b> gelobt" is the natural order, not <i>Gestern hat der Chef mich gelobt</i> (possible, but it stresses the boss). The hard error is stuffing two elements into the Vorfeld: <i>Gestern ich habe den Antrag eingereicht</i> ✗, <i>Den Antrag letzte Woche habe ich eingereicht</i> ✗.',
        fa:'قاعدهٔ «فعل دوم» به‌اشتباه به «فاعل دوم» تعمیم داده می‌شود. خطای سخت: گذاشتن دو عنصر در Vorfeld ✗.'}},
  {type:'quiz',q:{en:'„Sie ist ___ wegen des Streiks mit dem Bus zur Arbeit gefahren."'},
   a:'heute',o:['zur Arbeit','mit dem Bus','wegen des Streiks'],
   ex:{en:'Kausal, Modal and Lokal are already filled, so only the <b>temporal</b> slot is open — and in TeKaMoLo it comes first: <b>heute</b> wegen des Streiks mit dem Bus zur Arbeit.'}}
 ]},

/* ================= 8 · Nominalisation both ways ================= */
{id:'nominalisierung-b2',ic:'🏛️',lv:5,sk:'Style',
 title:{en:'Clause ⇄ noun phrase',fa:'تبدیل بند به گروه اسمی و برعکس'},
 sub:{en:'weil → wegen, obwohl → trotz, damit → zu',fa:'weil → wegen، obwohl → trotz، damit → zu'},
 blocks:[
  {type:'text',md:{en:'Every subordinate clause in German has a nominal twin: a <b>preposition + noun</b> that carries the same relation in half the words. B2 asks you to travel in <b>both</b> directions — compress for a dense opening sentence, expand when an official text has to be explained to a human.',
        fa:'هر جملهٔ پیرو آلمانی یک همزاد اسمی دارد: <b>حرف اضافه + اسم</b> با همان معنا در نیمی از کلمات. B2 از تو می‌خواهد در <b>هر دو</b> جهت حرکت کنی.'}},
  {type:'table',head:['Conjunction','Preposition','Relation','Example'],
   rows:[['weil','*wegen / aufgrund + Gen','cause','wegen des Streiks'],
         ['obwohl','*trotz + Gen','concession','trotz der Kritik'],
         ['nachdem','*nach + Dat','time, after','nach dem Abschluss'],
         ['bevor','*vor + Dat','time, before','vor der Abreise'],
         ['während','*während + Gen','time, during','während der Sitzung'],
         ['damit / um … zu','*zu / zur + Dat','purpose','zur Steigerung der Qualität'],
         ['indem','*durch + Akk','means','durch den Abbau von Stellen'],
         ['wenn / falls','*bei + Dat','condition','bei Nichtzahlung'],
         ['sodass','*infolge + Gen','consequence','infolge der Verzögerung']],
   cap:{en:'the relation chooses the preposition',fa:'رابطه است که حرف اضافه را انتخاب می‌کند'}},
  {type:'steps',items:[
   {en:'Clause → phrase: find the verb (<i>streiken</i>) and turn it into its noun (<i>der Streik</i>).',fa:'بند → عبارت: فعل را پیدا کن و به اسم تبدیلش کن.'},
   {en:'Choose the preposition by the <b>relation</b>, not by the word: cause → <i>wegen</i>, concession → <i>trotz</i>.',fa:'حرف اضافه را بر پایهٔ <b>رابطه</b> انتخاب کن، نه بر پایهٔ کلمه.'},
   {en:'Put the noun in the case that preposition demands, and move the old object into the Genitive: <i>die Daten prüfen</i> → <i>die Prüfung <b>der Daten</b></i>.',fa:'اسم را در حالتِ آن حرف اضافه بگذار و مفعول قدیم را به حالت اضافی ببر.'},
   {en:'Phrase → clause (the harder direction): read the noun, recover the verb, then ask <b>who</b> the subject was — the noun has hidden it.',fa:'عبارت → بند (جهت سخت‌تر): اسم را بخوان، فعل را بازیاب، و بپرس فاعل چه کسی بود.'}]},
  {type:'examples',items:[
   {de:'Wegen des schlechten Wetters wurde der Flug gestrichen.',en:'Because of the bad weather the flight was cancelled.',say:'Wegen des schlechten Wetters wurde der Flug gestrichen.'},
   {de:'Trotz heftiger Kritik hielt die Ministerin an dem Plan fest.',en:'Despite fierce criticism the minister stuck to the plan.',say:'Trotz heftiger Kritik hielt die Ministerin an dem Plan fest.'},
   {de:'Nach Abschluss des Studiums arbeitete sie im Ausland.',en:'After finishing her degree she worked abroad.',say:'Nach Abschluss des Studiums arbeitete sie im Ausland.'},
   {de:'Zur Steigerung der Effizienz wurden neue Geräte angeschafft.',en:'New devices were purchased in order to increase efficiency.',say:'Zur Steigerung der Effizienz wurden neue Geräte angeschafft.'},
   {de:'Die Kosten wurden durch den Abbau von Stellen gesenkt.',en:'Costs were cut by reducing the number of posts.',say:'Die Kosten wurden durch den Abbau von Stellen gesenkt.'},
   {de:'Bei Nichtzahlung erlischt der Anspruch.',en:'In the event of non-payment the claim lapses.',say:'Bei Nichtzahlung erlischt der Anspruch.'}]},
  {type:'contrast',cols:[
   {t:'Nominal — dense',md:{en:'„<b>Aufgrund der verspäteten Lieferung</b> musste die Produktion ruhen."<br>One compact phrase. Perfect as the <b>first</b> sentence of a report: it sets the frame without a second clause.'}},
   {t:'Verbal — breathable',md:{en:'„Die Produktion musste ruhen, <b>weil die Lieferung zu spät kam</b>."<br>Longer, but it names the actor and the time. Use it when the reader must actually follow the argument.'}}]},
  {type:'warn',md:{en:'Nominal style <b>hides the subject</b> — which is why officials love it, and why it is a trap in your own writing: „<i>Nach Prüfung der Unterlagen</i>" does not say who did the checking. The second trap is the <b>Genitivkette</b>: <i>die Verbesserung der Qualität der Produkte der Firma</i> ✗ — unreadable. Break any chain after <b>one</b> Genitive: <i>die Verbesserung der Produktqualität bei diesem Hersteller</i>.',
        fa:'سبک اسمی <b>فاعل را پنهان می‌کند</b> و دام دوم <b>زنجیرهٔ اضافی</b> است: بعد از <b>یک</b> حالت اضافی زنجیره را بشکن.'}},
  {type:'tip',md:{en:'A workable ratio in B2 writing: nominal style for the <b>opening</b> and for headings, verbal style for the body. If you read a paragraph aloud and run out of breath, you have gone too nominal — Germans call the extreme form <i>Behördendeutsch</i>, and it is not a compliment.',
        fa:'نسبت کارآمد: سبک اسمی برای <b>شروع</b> و تیترها، سبک فعلی برای متن.'}},
  {type:'quiz',q:{en:'Rewrite verbally: „Trotz seiner großen Erfahrung bekam er die Stelle nicht."'},
   a:'Obwohl er große Erfahrung hatte, bekam er die Stelle nicht.',
   o:['Trotzdem er große Erfahrung hatte, bekam er die Stelle nicht.','Trotz er große Erfahrung hatte, bekam er die Stelle nicht.','Dennoch er große Erfahrung hatte, bekam er die Stelle nicht.'],
   ex:{en:'<i>trotz</i> + Genitive is the nominal form of the concession; its clause partner is the subordinator <b>obwohl</b> with the verb at the end. <i>trotzdem</i> and <i>dennoch</i> are adverbs, <i>trotz</i> cannot take a clause.'}}
 ]},

/* ================= 9 · Every kind of noun modifier ================= */
{id:'attribut-typen',ic:'🧩',lv:5,sk:'Adjectives',
 title:{en:'Six ways to modify a noun',fa:'شش راه برای توصیف اسم'},
 sub:{en:'From one adjective to a whole participial phrase',fa:'از یک صفت تا یک عبارت وصفی کامل'},
 blocks:[
  {type:'text',md:{en:'Anything that adds information to a noun is an <b>Attribut</b>. German has six kinds, and they are not interchangeable: they differ in <b>weight</b> (how much they slow the reader) and in <b>register</b> (speech vs. report). Choosing well is most of what separates B2 writing from C1 writing.',
        fa:'هر چیزی که به اسم اطلاعات بیفزاید <b>Attribut</b> است. آلمانی شش نوع دارد که در <b>وزن</b> و <b>سطح زبانی</b> متفاوت‌اند.'}},
  {type:'table',head:['Type','Example','Weight / register'],
   rows:[['Adjektiv','*die neue Regel','light, any register'],
         ['Genitivattribut','*die Regel des Hauses','light, written'],
         ['Präpositionalattribut','*die Regel für Gäste','light, any register'],
         ['Relativsatz','*die Regel, die seit Mai gilt','medium, speech-friendly'],
         ['Partizipialattribut','*die seit Mai geltende Regel','heavy, written only'],
         ['Apposition','*die Regel, eine Neuerung von 2024, …','medium, written']],
   cap:{en:'same content, six weights',fa:'یک محتوا، شش وزن'}},
  {type:'rule',md:{en:'The <b>participial attribute</b> is a relative clause folded up and pushed <b>between article and noun</b>. <b>Partizip I</b> (Infinitiv + d) is active and simultaneous: <i>die <b>steigende</b> Zahl</i> = die Zahl, die steigt. <b>Partizip II</b> is passive or completed: <i>die <b>unterschriebenen</b> Unterlagen</i> = die Unterlagen, die unterschrieben worden sind. Either way it takes <b>normal adjective endings</b>.',
        fa:'<b>صفت وصفی فعلی</b> یک جملهٔ موصولی تاشده است که <b>میان حرف تعریف و اسم</b> می‌نشیند. <b>Partizip I</b> فعال و همزمان؛ <b>Partizip II</b> مجهول یا تمام‌شده. پایانهٔ صفتی معمولی می‌گیرد.'}},
  {type:'examples',items:[
   {de:'Die steigende Zahl der Bewerbungen freut die Personalabteilung.',en:'The rising number of applications pleases the HR department.',say:'Die steigende Zahl der Bewerbungen freut die Personalabteilung.'},
   {de:'Das vom Bundestag beschlossene Gesetz tritt im Januar in Kraft.',en:'The law passed by parliament comes into force in January.',say:'Das vom Bundestag beschlossene Gesetz tritt im Januar in Kraft.'},
   {de:'Die Nachfrage nach Elektroautos ist deutlich gewachsen.',en:'Demand for electric cars has grown markedly.',say:'Die Nachfrage nach Elektroautos ist deutlich gewachsen.'},
   {de:'Der Vorsitzende des Ausschusses erklärte den Beschluss.',en:'The chair of the committee explained the decision.',say:'Der Vorsitzende des Ausschusses erklärte den Beschluss.'},
   {de:'Wir sprachen mit Frau Weber, der Leiterin der Abteilung.',en:'We spoke with Ms Weber, the head of the department.',say:'Wir sprachen mit Frau Weber, der Leiterin der Abteilung.'}]},
  {type:'contrast',cols:[
   {t:'Relativsatz',md:{en:'„das Gesetz, <b>das der Bundestag beschlossen hat</b>"<br>Information arrives <b>after</b> the noun, in normal order. Speakable, and the only choice in conversation.'}},
   {t:'Partizipialattribut',md:{en:'„das <b>vom Bundestag beschlossene</b> Gesetz"<br>Information arrives <b>before</b> the noun. Shorter, denser, typical of press and law. English cannot do this with a long phrase, which is why it feels alien.'}}]},
  {type:'text',md:{en:'The <b>apposition</b> is the cheapest upgrade in German writing: a second noun phrase set off by commas that renames the first. It copies the <b>case</b> of the noun it explains: „Wir sprachen mit <b>Frau Weber</b>, <b>der</b> Leiterin der Abteilung" (mit + Dativ → Dativ in the apposition too).',
        fa:'<b>Apposition</b> ارزان‌ترین ارتقای نوشتار آلمانی است: گروه اسمی دومی میان ویرگول که <b>حالت</b> اسم اول را تکرار می‌کند.'}},
  {type:'steps',items:[
   {en:'One word of information? Use an adjective.',fa:'یک کلمه اطلاعات؟ صفت.'},
   {en:'Possessor or belonging? Genitive attribute.',fa:'مالکیت یا تعلق؟ Attribut اضافی.'},
   {en:'A whole event with its own verb, and you are speaking? Relative clause.',fa:'یک رویداد با فعل خودش، در گفتار؟ جملهٔ موصولی.'},
   {en:'The same event, and you are writing a report? Fold it into a participial attribute.',fa:'همان رویداد در گزارش؟ به Attribut وصفی تبدیلش کن.'},
   {en:'A second name or role for the same thing? Apposition — and copy the case.',fa:'نام یا نقش دوم برای همان چیز؟ Apposition — و حالت را تکرار کن.'}]},
  {type:'warn',md:{en:'Three real errors. <b>1)</b> Dropping the ending: <i>das vom Bundestag beschlossen Gesetz</i> ✗ — a participial attribute is an adjective and must be declined: <b>beschlossene</b>. <b>2)</b> Putting the phrase after the noun, English-style: <i>das Gesetz beschlossen vom Bundestag</i> ✗. <b>3)</b> Giving the apposition the wrong case: <i>mit Frau Weber, die Leiterin</i> ✗ → <b>der Leiterin</b>.',
        fa:'سه خطا: حذف پایانه ✗؛ گذاشتن عبارت بعد از اسم به سبک انگلیسی ✗؛ حالت نادرست در Apposition ✗.'}},
  {type:'tip',md:{en:'Length limit for a participial attribute: if the reader has to hold more than about four words before reaching the noun, unfold it back into a relative clause. Density is a tool, not a virtue.',
        fa:'حدّ طول: اگر خواننده باید بیش از چهار کلمه را تا رسیدن به اسم نگه دارد، به جملهٔ موصولی برگردان.'}},
  {type:'quiz',q:{en:'„Der Bericht, ___ Zahlen veraltet sind, wurde zurückgezogen."'},
   a:'dessen',o:['deren','den','der'],
   ex:{en:'A Genitive attribute inside a relative clause: the figures belong to the report (<i>der Bericht</i>, masculine), so the relative pronoun is <b>dessen</b>. <i>deren</i> would be feminine or plural.'}}
 ]},

/* ================= 10 · Modals in the perfect ================= */
{id:'modalverben-perfekt',ic:'🔧',lv:5,sk:'Verbs',
 title:{en:'Modals in the Perfekt',fa:'فعل‌های مُدال در ماضی نقلی'},
 sub:{en:'Ich habe arbeiten müssen — the double infinitive',fa:'مصدر دوگانه'},
 blocks:[
  {type:'text',md:{en:'„I had to work yesterday." You already know the easy way out — the Präteritum: <i>Ich musste gestern arbeiten.</i> Keep using it in speech, it is the normal form. But you must be able to <b>recognise and build</b> the Perfekt, because it is unavoidable with <b>hätte</b>, in subordinate clauses and in anything written.',
        fa:'«دیروز باید کار می‌کردم.» راه آسان Präteritum است: <i>Ich musste gestern arbeiten.</i> اما ساختن ماضی نقلی هم لازم است — بخصوص با <b>hätte</b> و در جملهٔ پیرو.'}},
  {type:'rule',md:{en:'A modal <b>with</b> a second verb forms the Perfekt with <b>haben</b> + full-verb infinitive + <b>modal infinitive</b>: <i>Ich <b>habe</b> gestern lange <b>arbeiten müssen</b>.</i> That is the <b>double infinitive</b> (<i>doppelter Infinitiv</i>). A modal <b>alone</b> behaves normally and takes a real participle: <i>Das habe ich nicht <b>gewollt</b>.</i>',
        fa:'مُدال <b>با</b> فعل دوم: <b>haben</b> + مصدر فعل اصلی + <b>مصدر مُدال</b> — همان <b>مصدر دوگانه</b>. مُدال <b>تنها</b>: اسم مفعول واقعی می‌گیرد.'}},
  {type:'table',head:['Präteritum (preferred in speech)','Perfekt','Modal alone'],
   rows:[['ich musste arbeiten','*ich habe arbeiten müssen','ich habe es gemusst'],
         ['er konnte nicht kommen','*er hat nicht kommen können','er hat es nicht gekonnt'],
         ['wir wollten kündigen','*wir haben kündigen wollen','wir haben es gewollt'],
         ['sie durfte nicht fahren','*sie hat nicht fahren dürfen','sie hat es nicht gedurft'],
         ['ich sollte warten','*ich habe warten sollen','—']],
   cap:{en:'haben, always — even with gehen and fahren',fa:'همیشه haben — حتی با gehen و fahren'}},
  {type:'examples',items:[
   {de:'Ich habe gestern bis acht arbeiten müssen.',en:'I had to work until eight yesterday.',say:'Ich habe gestern bis acht arbeiten müssen.'},
   {de:'Sie hat den Zug nicht mehr erreichen können.',en:'She was no longer able to catch the train.',say:'Sie hat den Zug nicht mehr erreichen können.'},
   {de:'Er hat nach Berlin fahren müssen.',en:'He had to go to Berlin.',say:'Er hat nach Berlin fahren müssen.'},
   {de:'Das habe ich wirklich nicht gewollt.',en:'I really did not intend that.',say:'Das habe ich wirklich nicht gewollt.'},
   {de:'Wir hätten den Termin verschieben können.',en:'We could have postponed the appointment.',say:'Wir hätten den Termin verschieben können.'}]},
  {type:'contrast',cols:[
   {t:'Modal + Infinitiv',md:{en:'„Ich habe <b>arbeiten müssen</b>."<br>Two infinitives, modal last. The modal has a verb to govern, so it stays an infinitive.'}},
   {t:'Modal as full verb',md:{en:'„Ich habe <b>gemusst</b>." / „Ich kann kein Deutsch" → „Ich habe kein Deutsch <b>gekonnt</b>."<br>No second verb → a genuine participle with <b>ge-</b>.'}}]},
  {type:'rule',md:{en:'In a <b>subordinate clause</b> the finite verb would normally go last — but it cannot stand behind a double infinitive. So it moves <b>in front of it</b>: „Ich weiß, dass sie das Angebot nicht <b>hat</b> ablehnen können." Same with <i>hätte</i>: „…, weil ich <b>hätte</b> arbeiten müssen."',
        fa:'در <b>جملهٔ پیرو</b>، فعل صرف‌شده نمی‌تواند پشت مصدر دوگانه بایستد، پس <b>پیش از آن</b> می‌آید.'}},
  {type:'text',md:{en:'The same double-infinitive pattern belongs to <b>lassen</b> and to the perception verbs <b>sehen</b> and <b>hören</b>: <i>Ich habe mir die Haare <b>schneiden lassen</b>.</i> <i>Er hat sich nicht <b>überzeugen lassen</b>.</i> <i>Ich habe das Telefon nicht <b>klingeln hören</b>.</i> <b>lassen</b> is the one you will use daily.',
        fa:'همین الگو برای <b>lassen</b> و فعل‌های ادراکی <b>sehen</b> و <b>hören</b> هم هست. <b>lassen</b> را روزمره به کار می‌بری.'}},
  {type:'warn',md:{en:'Four shapes that do not exist. <i>Ich habe gemusst arbeiten</i> ✗ (order), <i>Ich bin fahren müssen</i> ✗ (always <b>haben</b>, never <i>sein</i>, even for <i>fahren/gehen</i>), <i>Ich habe arbeiten gemusst</i> ✗ (no participle when a second verb is present), and <i>…, weil ich arbeiten müssen habe</i> ✗ (the auxiliary goes <b>before</b> the two infinitives).',
        fa:'چهار شکل که وجود ندارند: ترتیب غلط ✗؛ <i>bin … müssen</i> ✗؛ اسم مفعول مُدال با فعل دوم ✗؛ فعل کمکی بعد از دو مصدر ✗.'}},
  {type:'tip',md:{en:'Rule of thumb for real conversation: use the <b>Präteritum</b> for modals (musste, konnte, wollte, durfte, sollte) and save the double infinitive for the places where you have no choice — after <b>hätte</b>, and inside a <b>dass</b>-clause. That is exactly how Germans do it.',
        fa:'قاعدهٔ عملی: در گفتار از <b>Präteritum</b> مُدال‌ها استفاده کن و مصدر دوگانه را برای جاهای ناگزیر نگه دار.'}},
  {type:'quiz',q:{en:'„Er ärgert sich, dass er die Stelle ___ bekommen können."'},
   a:'hätte',o:['haben','gehabt','hätte haben'],
   ex:{en:'A double infinitive (<i>bekommen können</i>) pushes the finite verb <b>in front</b> of it, and the unreal past needs <b>hätte</b>: „…, dass er die Stelle <b>hätte</b> bekommen können."'}}
 ]},

/* ================= 11 · Verb complexes ================= */
{id:'verbgefuege',ic:'⚙️',lv:5,sk:'Verbs',
 title:{en:'lassen and the bare infinitive',fa:'lassen و مصدر بدون zu'},
 sub:{en:'lassen · bleiben/gehen/kommen + Infinitiv · sehen, hören, helfen',fa:'lassen و فعل‌هایی که مصدر ساده می‌گیرند'},
 blocks:[
  {type:'text',md:{en:'A small group of German verbs takes a <b>bare infinitive</b> — no <i>zu</i>, no comma. You know the modals. The group is bigger than that, and <b>lassen</b> is its star: a single verb with four distinct meanings, all of them everyday.',
        fa:'گروه کوچکی از فعل‌های آلمانی <b>مصدر ساده</b> می‌گیرند — بدون <i>zu</i> و بدون ویرگول. ستارهٔ این گروه <b>lassen</b> است: یک فعل با چهار معنای متفاوت.'}},
  {type:'table',head:['Meaning of lassen','Example','English'],
   rows:[['1 leave / stop','*Lass das! / Ich habe den Laptop im Büro liegen lassen.','stop that / I left the laptop at the office'],
         ['2 allow','*Mein Chef lässt mich von zu Hause arbeiten.','my boss lets me work from home'],
         ['3 have something done','*Ich lasse das Auto reparieren.','I am having the car repaired'],
         ['4 sich lassen = can be done','*Das Problem lässt sich lösen.','the problem can be solved']],
   cap:{en:'one verb, four jobs — context does the sorting',fa:'یک فعل، چهار کار — بافت تفکیک می‌کند'}},
  {type:'rule',md:{en:'Meaning 4 is a genuine <b>passive substitute</b>: <b>sich lassen + Infinitiv</b> = <i>können + Passiv</i>. „Der Schaden <b>lässt sich</b> nicht mehr <b>beheben</b>" = „Der Schaden <b>kann</b> nicht mehr <b>behoben werden</b>." Shorter, lighter, and extremely common in manuals, reviews and spoken German.',
        fa:'معنای چهارم جانشین واقعی مجهول است: <b>sich lassen + مصدر</b> = <i>können + مجهول</i> — کوتاه‌تر و رایج‌تر.'}},
  {type:'contrast',cols:[
   {t:'können + Passiv',md:{en:'„Das Problem <b>kann gelöst werden</b>."<br>Three verb forms, formal weight. Right for a report or a legal text.'}},
   {t:'sich lassen + Infinitiv',md:{en:'„Das Problem <b>lässt sich lösen</b>."<br>Two verb forms, no agent, no <i>werden</i>. Right for speech, e-mail, product description.'}}]},
  {type:'text',md:{en:'Three more verbs take a bare infinitive with a meaning of their own. <b>bleiben</b> + Infinitiv = to stay in a position (<i>sitzen bleiben, liegen bleiben, stehen bleiben</i>). <b>gehen</b> + Infinitiv = to go and do (<i>einkaufen gehen, schwimmen gehen</i>). <b>kommen</b> + Infinitiv = to come and do (<i>Sie kommt uns besuchen</i>).',
        fa:'سه فعل دیگر مصدر ساده می‌گیرند: <b>bleiben</b> (ماندن در وضعیت)، <b>gehen</b> (رفتن برای انجام کاری)، <b>kommen</b> (آمدن برای انجام کاری).'}},
  {type:'examples',items:[
   {de:'Bitte bleiben Sie sitzen.',en:'Please stay seated.',say:'Bitte bleiben Sie sitzen.'},
   {de:'Wir gehen nach der Arbeit noch einkaufen.',en:'We are going shopping after work.',say:'Wir gehen nach der Arbeit noch einkaufen.'},
   {de:'Sie kommt uns morgen besuchen.',en:'She is coming to visit us tomorrow.',say:'Sie kommt uns morgen besuchen.'},
   {de:'Ich habe meinen Laptop im Büro liegen lassen.',en:'I left my laptop at the office.',say:'Ich habe meinen Laptop im Büro liegen lassen.'},
   {de:'Der Schaden hätte sich vermeiden lassen.',en:'The damage could have been avoided.',say:'Der Schaden hätte sich vermeiden lassen.'}]},
  {type:'table',head:['Verb','Pattern','Example'],
   rows:[['sehen','Akk + Infinitiv','*Ich habe ihn kommen sehen.'],
         ['hören','Akk + Infinitiv','*Ich habe das Telefon nicht klingeln hören.'],
         ['spüren / fühlen','Akk + Infinitiv','*Sie spürte die Spannung steigen.'],
         ['helfen','Dat + Infinitiv','*Ich helfe dir aufräumen.'],
         ['lehren / lernen','Akk + Infinitiv','*Er hat mich schwimmen gelehrt.']],
   cap:{en:'no zu with any of these',fa:'هیچ‌کدام zu نمی‌گیرند'}},
  {type:'warn',md:{en:'The English-driven error is inserting <i>zu</i>: „I help you <b>to</b> tidy up" → <i>Ich helfe dir aufzuräumen</i> is clumsy; say <b>Ich helfe dir aufräumen</b>, or, with a longer object, the comma version „Ich helfe dir, die Tabelle auszufüllen." The second error is treating <i>sich lassen</i> as reflexive: <i>Das Problem lässt sich selbst lösen</i> means the problem solves <b>itself</b> — drop <i>selbst</i> if you mean „can be solved".',
        fa:'خطای ناشی از انگلیسی: افزودن <i>zu</i>. و خطای دوم: فهم <i>sich lassen</i> به‌عنوان فعل بازتابی — <i>selbst</i> معنا را عوض می‌کند.'}},
  {type:'tip',md:{en:'Three <i>lassen</i> sentences worth owning outright: <b>Lass mich das machen.</b> (allow) <b>Ich lasse mir die Haare schneiden.</b> (have done) <b>Das lässt sich machen.</b> (can be done — a gentle German „yes, that works").',
        fa:'سه جمله با lassen که ارزش حفظ کردن دارند: <b>Lass mich das machen. / Ich lasse mir die Haare schneiden. / Das lässt sich machen.</b>'}},
  {type:'quiz',q:{en:'Which sentence means „the file cannot be opened"?'},
   a:'Die Datei lässt sich nicht öffnen.',
   o:['Die Datei lässt nicht öffnen.','Die Datei lässt sich nicht zu öffnen.','Die Datei lässt sich nicht geöffnet.'],
   ex:{en:'The passive substitute needs all three parts: <b>lässt</b> + <b>sich</b> + bare <b>Infinitiv</b>. No <i>zu</i>, no participle.'}}
 ]},

/* ================= 12 · es as a correlate ================= */
{id:'korrelat',ic:'🔗',lv:5,sk:'Sentences',
 title:{en:'es as a correlate',fa:'es به‌عنوان نشانهٔ پیش‌اشاره'},
 sub:{en:'Es freut mich, dass … — obligatory, optional or wrong',fa:'کجا لازم، کجا اختیاری، کجا غلط'},
 blocks:[
  {type:'text',md:{en:'A <b>Korrelat</b> is a placeholder: a little <b>es</b> that occupies a slot in the main clause and announces that the real content is coming as a clause behind it. „<b>Es</b> freut mich, <b>dass Sie zusagen</b>." Whether you need it is not a matter of taste — each verb and adjective decides, and B2 exams test exactly this.',
        fa:'<b>Korrelat</b> یک جانشین است: <b>es</b>ِ کوچکی که جایگاهی را در جملهٔ اصلی پر می‌کند و خبر می‌دهد محتوای اصلی به‌صورت یک بند از پی می‌آید. لازم‌بودنش سلیقه‌ای نیست.'}},
  {type:'table',head:['Status','Pattern','Example'],
   rows:[['*obligatory','Adjektiv-Komplement: <i>finden / halten für</i>','*Ich finde es gut, dass das Thema diskutiert wird.'],
         ['*obligatory','es in the Vorfeld as subject','*Es freut mich, dass Sie kommen.'],
         ['*obligatory','es ist + Adjektiv','*Es ist wichtig, dass alle informiert werden.'],
         ['optional','verbs of perceiving / understanding','Ich kann (es) verstehen, dass Sie enttäuscht sind.'],
         ['*wrong','plain dass-object: <i>hoffen, glauben, sagen, wissen</i>','*Ich hoffe es, dass er kommt. ✗'],
         ['*wrong','prepositional-object verbs take <b>da-</b>, not es','*Wir rechnen damit, dass die Kosten steigen.']],
   cap:{en:'the verb decides, not the meaning',fa:'فعل تعیین می‌کند، نه معنا'}},
  {type:'rule',md:{en:'If <b>es</b> is the <b>subject</b> and stands in the Vorfeld, it is obligatory — German will not start a sentence with an empty slot. But move the clause to the front and the placeholder has nothing left to hold: „<b>Dass</b> die Preise steigen, überrascht niemanden." No <i>es</i> at all.',
        fa:'اگر <b>es</b> فاعل باشد و در Vorfeld بنشیند، الزامی است. اما اگر بند به ابتدا برود، جانشین حذف می‌شود.'}},
  {type:'contrast',cols:[
   {t:'Clause behind → es needed',md:{en:'„<b>Es</b> überrascht niemanden, dass die Preise steigen."<br>The front slot must be filled, and the real subject is still to come — <b>es</b> holds the place.'}},
   {t:'Clause in front → no es',md:{en:'„<b>Dass die Preise steigen</b>, überrascht niemanden."<br>The clause <b>is</b> the front slot. „Dass die Preise steigen, <i>es</i> überrascht niemanden" ✗.'}}]},
  {type:'examples',items:[
   {de:'Es freut mich, dass Sie zusagen.',en:'I am glad that you are accepting.',say:'Es freut mich, dass Sie zusagen.'},
   {de:'Ich finde es gut, dass das Thema offen diskutiert wird.',en:'I think it is good that the topic is being discussed openly.',say:'Ich finde es gut, dass das Thema offen diskutiert wird.'},
   {de:'Wir halten es für sinnvoll, die Frist zu verlängern.',en:'We consider it sensible to extend the deadline.',say:'Wir halten es für sinnvoll, die Frist zu verlängern.'},
   {de:'Mir ist nicht aufgefallen, dass die Zahlen fehlen.',en:'I did not notice that the figures were missing.',say:'Mir ist nicht aufgefallen, dass die Zahlen fehlen.'},
   {de:'Ich hoffe, dass der Termin bleibt.',en:'I hope the appointment stands.',say:'Ich hoffe, dass der Termin bleibt.'}]},
  {type:'steps',items:[
   {en:'Ask what the clause <b>is</b> in the main sentence: subject or object?',fa:'بپرس بند در جملهٔ اصلی چه نقشی دارد: فاعل یا مفعول؟'},
   {en:'Does the verb demand a preposition (<i>rechnen mit, bestehen auf</i>)? Then use <b>da(r)-</b>, never es.',fa:'آیا فعل حرف اضافه می‌خواهد؟ پس <b>da(r)-</b>، نه es.'},
   {en:'Is there an adjective complement (<i>gut, wichtig, schade, für sinnvoll</i>)? Then <b>es</b> is obligatory.',fa:'آیا متمم صفتی دارد؟ پس <b>es</b> الزامی است.'},
   {en:'Is the Vorfeld empty and the clause behind? Fill it with <b>es</b>.',fa:'آیا Vorfeld خالی است و بند پشت آن می‌آید؟ با <b>es</b> پرش کن.'},
   {en:'Did you move the clause to the front, or is another element (<i>mir, dem Kunden</i>) already in the Vorfeld? Then drop <b>es</b>.',fa:'اگر بند به ابتدا رفته یا عنصر دیگری در Vorfeld است، <b>es</b> را حذف کن.'}]},
  {type:'warn',md:{en:'The signature B2 error is an <b>extra es</b> after verbs that take a plain dass-object: <i>Ich hoffe es, dass er kommt</i> ✗, <i>Ich glaube es, dass das stimmt</i> ✗, <i>Er hat es gesagt, dass er kommt</i> ✗ (that one means „he said <b>it</b>" — a different sentence). The mirror error is a <b>missing es</b> with an adjective: <i>Ich finde gut, dass…</i> ✗ → <b>Ich finde es gut, dass…</b>',
        fa:'خطای شاخص B2: <b>es</b>ِ اضافی بعد از فعل‌هایی که مفعول dass ساده می‌گیرند ✗؛ و خطای آینه‌ای: <b>es</b>ِ حذف‌شده با صفت ✗.'}},
  {type:'tip',md:{en:'Learn the three high-frequency frames whole, and you cover most exam items: <b>Es ist wichtig/schade/kein Problem, dass …</b> · <b>Ich finde es gut/falsch, dass …</b> · <b>Es freut/ärgert/wundert mich, dass …</b>',
        fa:'سه قالب پرکاربرد را کامل حفظ کن: <b>Es ist wichtig, dass … / Ich finde es gut, dass … / Es freut mich, dass …</b>'}},
  {type:'quiz',q:{en:'Which sentence is correct?'},
   a:'Ich halte es für sinnvoll, die Frist zu verlängern.',
   o:['Ich halte für sinnvoll, die Frist zu verlängern.','Ich halte es für sinnvoll, die Frist verlängern.','Ich hoffe es, dass die Frist verlängert wird.'],
   ex:{en:'<i>halten für</i> + adjective always needs the correlate <b>es</b>, and the following clause needs <b>zu</b>. <i>hoffen</i>, by contrast, takes no <i>es</i> at all.'}}
 ]},

/* ================= 13 · The concession family ================= */
{id:'konzessiv-b2',ic:'🛡️',lv:5,sk:'Connectors',
 title:{en:'Concession: obwohl and its family',fa:'خانوادهٔ امتیازدهی'},
 sub:{en:'obwohl · trotzdem · zwar…aber · selbst wenn',fa:'obwohl · trotzdem · zwar…aber · selbst wenn'},
 blocks:[
  {type:'text',md:{en:'A <b>concession</b> says: this fact speaks against my conclusion, and I am keeping the conclusion anyway. It is the single most useful move in a B2 discussion or Stellungnahme — and German offers about ten ways to make it, differing in <b>word order</b> and in <b>register</b>, not in meaning.',
        fa:'<b>امتیازدهی</b> می‌گوید: این واقعیت خلاف نتیجهٔ من است و باز هم نتیجه را نگه می‌دارم. آلمانی حدود ده راه برای آن دارد که در <b>ترتیب کلمات</b> و <b>سطح زبانی</b> تفاوت دارند، نه در معنا.'}},
  {type:'table',head:['Word','Class / word order','Register'],
   rows:[['obwohl','Subjunktion — verb last','*neutral, always safe'],
         ['obgleich / obschon','Subjunktion — verb last','formal, slightly literary'],
         ['wenngleich','Subjunktion — verb last','*formal writing, press'],
         ['auch wenn','Subjunktion — verb last','neutral, also hypothetical'],
         ['selbst wenn','Subjunktion — verb last','*emphatic: even if'],
         ['trotzdem','Adverb — position 1, inversion','*neutral, very frequent'],
         ['dennoch','Adverb — position 1, inversion','formal'],
         ['gleichwohl','Adverb — position 1, inversion','*very formal, almost legal'],
         ['zwar … aber','correlative pair','neutral, structuring'],
         ['trotz + Gen','Preposition','*neutral, nominal style'],
         ['ungeachtet + Gen','Preposition','very formal']],
   cap:{en:'eleven tools, three word orders',fa:'یازده ابزار، سه ترتیب کلمات'}},
  {type:'examples',items:[
   {de:'Obwohl es stark regnete, fand das Fest statt.',en:'Although it was raining hard, the festival took place.',say:'Obwohl es stark regnete, fand das Fest statt.'},
   {de:'Es regnete stark; dennoch fand das Fest statt.',en:'It was raining hard; the festival took place nonetheless.',say:'Es regnete stark; dennoch fand das Fest statt.'},
   {de:'Der Plan ist, wenngleich er teuer ist, durchaus sinnvoll.',en:'The plan, expensive though it is, makes good sense.',say:'Der Plan ist, wenngleich er teuer ist, durchaus sinnvoll.'},
   {de:'Trotz aller Bedenken wurde das Gesetz verabschiedet.',en:'Despite all reservations the law was passed.',say:'Trotz aller Bedenken wurde das Gesetz verabschiedet.'},
   {de:'Das Angebot ist zwar günstig, aber völlig unflexibel.',en:'The offer is cheap, admittedly, but totally inflexible.',say:'Das Angebot ist zwar günstig, aber völlig unflexibel.'}]},
  {type:'contrast',cols:[
   {t:'obwohl — a fact',md:{en:'„<b>Obwohl</b> er qualifiziert ist, bekommt er die Stelle nicht."<br>He <b>is</b> qualified. You concede something true.'}},
   {t:'auch wenn / selbst wenn — hypothetical',md:{en:'„<b>Selbst wenn</b> er qualifiziert wäre, bekäme er die Stelle nicht."<br>He may well not be. You concede something merely <b>possible</b> — and it often pulls a Konjunktiv II with it.'}}]},
  {type:'rule',md:{en:'<b>zwar … aber</b> is a frame, not a connector: <i>zwar</i> sits in the first half (usually in the middle field) and flags „yes, granted"; <i>aber</i> opens the second half with the point you actually want to make. The weight always lands <b>after</b> <i>aber</i> — which is why it is such a good tool for an argumentative text.',
        fa:'<b>zwar … aber</b> یک قالب است: <i>zwar</i> در نیمهٔ اول «بله، قبول» را نشان می‌دهد و <i>aber</i> نکتهٔ اصلی را می‌آورد. وزن همیشه <b>بعد از</b> aber می‌افتد.'}},
  {type:'warn',md:{en:'<b>trotzdem is not a subordinator.</b> <i>Trotzdem er krank war, kam er</i> ✗ — that is dialect or 19th-century German. Write <b>obwohl</b> er krank war, or „Er war krank; <b>trotzdem</b> kam er." Second trap: <b>trotz</b> takes a <b>noun in the Genitive</b>, never a clause: <i>trotz er krank war</i> ✗ → <b>trotz seiner Krankheit</b>. Third: <i>obwohl</i> never causes inversion — <i>obwohl war er krank</i> ✗.',
        fa:'<b>trotzdem حرف ربط پیروساز نیست</b> ✗. <b>trotz</b> اسم در حالت اضافی می‌گیرد، نه بند ✗. و <i>obwohl</i> هرگز معکوس‌سازی نمی‌آورد ✗.'}},
  {type:'tip',md:{en:'Register ladder for your own writing: speech → <b>obwohl / trotzdem</b>; a careful e-mail → <b>allerdings / dennoch</b>; a report or exam essay → <b>wenngleich / trotz + Gen / ungeachtet</b>. One concession per paragraph is persuasive; three in a row and the reader stops believing you.',
        fa:'نردبان سطح زبانی: گفتار → obwohl/trotzdem؛ ایمیل محتاط → allerdings/dennoch؛ گزارش و آزمون → wenngleich/trotz + اضافی.'}},
  {type:'text',md:{en:'One spoken habit worth recognising but not imitating in writing: Germans tack <b>„Obwohl …"</b> onto the end of a turn as an afterthought, with <b>main-clause</b> order — „Ich komme mit. <b>Obwohl</b>, ich bin eigentlich müde." That is a discourse marker, not a subordinator, and it belongs to speech only.',
        fa:'یک عادت گفتاری: آلمانی‌ها <b>«Obwohl …»</b> را با ترتیب جملهٔ اصلی به انتهای سخن می‌چسبانند — نشانگر گفتمانی است، نه حرف ربط؛ فقط در گفتار.'}},
  {type:'quiz',q:{en:'„___ es stark regnete, fand das Fest statt."'},
   a:'Obwohl',o:['Trotzdem','Trotz','Dennoch'],
   ex:{en:'The verb <i>regnete</i> stands at the end of the first clause, so the slot needs a <b>Subjunktion</b>: <b>obwohl</b>. <i>trotzdem</i> and <i>dennoch</i> are adverbs and would demand inversion, <i>trotz</i> would demand a Genitive noun.'}}
 ]},

/* ================= 14 · Reporting what was said ================= */
{id:'redewiedergabe',ic:'📰',lv:5,sk:'Konjunktiv',
 title:{en:'Reporting speech',fa:'نقل قول'},
 sub:{en:'dass + Indikativ · Konjunktiv I · laut / nach Angaben von',fa:'چهار راه برای نقل گفتهٔ دیگران'},
 blocks:[
  {type:'text',md:{en:'German has four ways to report what someone said, and they are <b>not</b> stylistic variants of one another — each belongs to a register. Choosing the wrong one is not a grammar mistake; it is a social one, like wearing a suit to the beach.',
        fa:'آلمانی چهار راه برای نقل گفتهٔ دیگران دارد و هر یک به سطح زبانی خاصی تعلق دارد. انتخاب نادرست، خطای دستوری نیست — خطای اجتماعی است.'}},
  {type:'table',head:['Option','Example','Where it belongs'],
   rows:[['dass + Indikativ','*Er hat gesagt, dass er müde ist.','everyday speech, e-mail'],
         ['main clause, no dass','*Er hat gesagt, er ist müde.','everyday speech'],
         ['Konjunktiv I','*Er sagte, er sei müde.','press, minutes, academic prose'],
         ['Konjunktiv II as substitute','*Sie erklärten, sie stimmten nicht zu.','where K I looks like the Indikativ'],
         ['laut / nach Angaben von / zufolge','*Laut dem Bericht steigen die Kosten.','news, reports — no verb needed']],
   cap:{en:'four registers, one message',fa:'چهار سطح زبانی، یک پیام'}},
  {type:'rule',md:{en:'<b>Konjunktiv I</b> = infinitive stem + <b>-e, -est, -e, -en, -et, -en</b>: <i>er komme, er habe, er werde, man gehe</i>. <b>sein</b> is irregular and the only one you really must memorise: <b>sei, seist, sei, seien, seiet, seien</b> — note the missing <i>-e</i> in <i>sei</i>.',
        fa:'<b>Konjunktiv I</b> = بن مصدر + <b>-e, -est, -e, -en, -et, -en</b>. <b>sein</b> بی‌قاعده است: <b>sei, seist, sei, seien, seiet, seien</b>.'}},
  {type:'rule',md:{en:'The <b>substitution rule</b>: whenever Konjunktiv I would be identical to the Indikativ — above all in the plural (<i>sie kommen</i>) and in the 1st person — you switch to <b>Konjunktiv II</b> so the reader can still see it is reported speech. <i>Die Abgeordneten erklärten, sie <b>stimmten</b> nicht zu.</i> With the passive and the future this usually means <b>würde</b>: <i>Die Zahlen <b>würden</b> noch geprüft.</i>',
        fa:'<b>قاعدهٔ جانشینی</b>: هر جا Konjunktiv I با اخباری یکسان شود — خصوصاً در جمع — به <b>Konjunktiv II</b> برو تا نقل‌قول‌بودن دیده شود.'}},
  {type:'examples',items:[
   {de:'Die Ministerin erklärte, der Haushalt sei ausgeglichen.',en:'The minister stated that the budget was balanced.',say:'Die Ministerin erklärte, der Haushalt sei ausgeglichen.'},
   {de:'Er betonte, er habe nichts von der Absprache gewusst.',en:'He stressed that he had known nothing of the arrangement.',say:'Er betonte, er habe nichts von der Absprache gewusst.'},
   {de:'Die Anwälte sagten, die Vorwürfe seien unbegründet.',en:'The lawyers said the accusations were unfounded.',say:'Die Anwälte sagten, die Vorwürfe seien unbegründet.'},
   {de:'Dem Bericht zufolge wurden Daten manipuliert.',en:'According to the report, data were manipulated.',say:'Dem Bericht zufolge wurden Daten manipuliert.'},
   {de:'Nach Angaben der Polizei gab es keine Verletzten.',en:'According to the police there were no injuries.',say:'Nach Angaben der Polizei gab es keine Verletzten.'}]},
  {type:'contrast',cols:[
   {t:'Spoken — dass + Indikativ',md:{en:'„Mein Kollege hat erzählt, <b>dass</b> er den Job <b>wechselt</b>."<br>Neutral. You are simply passing on information, and nobody hears any distance.'}},
   {t:'Journalistic — Konjunktiv I',md:{en:'„Der Kollege erklärte, er <b>wechsle</b> den Job."<br>The Konjunktiv marks the words as <b>somebody else\'s</b>. The writer neither confirms nor denies — that neutrality is its whole job.'}}]},
  {type:'text',md:{en:'The verb-free options are gold in exam writing because they need no Konjunktiv at all. <b>laut</b> + Dativ (<i>laut dem Bericht</i>, also <i>laut Bericht</i>) · <b>nach Angaben von</b> + Dativ (<i>nach Angaben der Polizei</i>) · <b>zufolge</b>, which comes <b>after</b> its noun with the Dativ (<i>dem Bericht zufolge</i>) · <b>gemäß</b> + Dativ, very formal.',
        fa:'گزینه‌های بی‌فعل در نوشتار آزمون طلا هستند: <b>laut</b> + داتیو، <b>nach Angaben von</b> + داتیو، <b>zufolge</b> پس از اسم با داتیو، و <b>gemäß</b> + داتیو.'}},
  {type:'warn',md:{en:'German does <b>not</b> backshift the tense the way English does. „He said he was tired" reports a present state, so German keeps the present: <b>Er sagte, er sei müde</b> — not <i>er wäre gewesen</i>, not <i>er war</i>. Only a genuinely earlier event moves back, and then it goes to <b>habe/sei + Partizip II</b>: <i>Er sagte, er habe den Brief <b>abgeschickt</b></i>. Second warning: Konjunktiv I in conversation sounds absurdly stiff — among friends use <b>dass + Indikativ</b>.',
        fa:'آلمانی زمان را مثل انگلیسی عقب نمی‌کشد: <b>Er sagte, er sei müde</b> — نه <i>er war</i>. فقط رویدادِ واقعاً پیشین با <b>habe/sei + اسم مفعول</b> می‌آید. و Konjunktiv I در گفتار دوستانه خشک و مصنوعی است.'}},
  {type:'tip',md:{en:'For reading the news, learn to spot three forms and you have cracked 90% of reported speech: <b>sei</b> (is), <b>habe</b> (has), <b>werde</b> (will). Every time you see one in a news text, a source is speaking — not the journalist.',
        fa:'برای خواندن خبر، سه فرم را بشناس: <b>sei</b>، <b>habe</b>، <b>werde</b>. هر جا یکی را دیدی، منبع سخن می‌گوید، نه خبرنگار.'}},
  {type:'quiz',q:{en:'„Der Vorstand teilte mit, die Zahlen ___ noch geprüft." (reported speech, passive)'},
   a:'würden',o:['werden','wurden','seien'],
   ex:{en:'Konjunktiv I of the passive would be <i>werden</i> — identical to the Indikativ — so the substitution rule sends you to Konjunktiv II: <b>würden</b> geprüft.'}}
 ]},

/* ================= 15 · Adjective government ================= */
{id:'adjektiv-rektion',ic:'📐',lv:5,sk:'Adjectives',
 title:{en:'Adjectives with a case or a preposition',fa:'حالت و حرف اضافهٔ صفت‌ها'},
 sub:{en:'stolz auf · zufrieden mit · bewusst + Genitiv',fa:'stolz auf · zufrieden mit · bewusst + اضافی'},
 blocks:[
  {type:'text',md:{en:'Verbs govern a case — and so do adjectives. <b>Rektion</b> is the same idea here: <i>stolz</i> demands <b>auf + Akkusativ</b>, <i>zufrieden</i> demands <b>mit + Dativ</b>, <i>bewusst</i> demands a bare <b>Genitiv</b>. These are the items that quietly decide a B2 exam, because no amount of general grammar will generate them.',
        fa:'فعل‌ها حالت را حکم می‌کنند — صفت‌ها هم. <b>Rektion</b> همان ایده است: <i>stolz</i> حرف اضافهٔ <b>auf + آکوزاتیو</b> می‌خواهد، <i>zufrieden</i> حتماً <b>mit + داتیو</b>، و <i>bewusst</i> حالت <b>اضافی</b>.'}},
  {type:'table',head:['Adjective','Preposition + case','Example'],
   rows:[['stolz','*auf + Akk','stolz auf ihre Tochter'],
         ['zufrieden','*mit + Dat','zufrieden mit dem Ergebnis'],
         ['verantwortlich','*für + Akk','verantwortlich für den Fehler'],
         ['abhängig','*von + Dat','abhängig von Subventionen'],
         ['interessiert','*an + Dat','interessiert an einer Zusammenarbeit'],
         ['bereit','*zu + Dat','bereit zu einem Kompromiss'],
         ['fähig','*zu + Dat','fähig zu großer Leistung'],
         ['überzeugt','*von + Dat','überzeugt von dem Konzept'],
         ['enttäuscht','*von + Dat','enttäuscht von der Reaktion'],
         ['gewöhnt','*an + Akk','an Stress gewöhnt'],
         ['schuld','*an + Dat','schuld an der Verzögerung'],
         ['typisch','*für + Akk','typisch für diese Branche'],
         ['einverstanden','*mit + Dat','einverstanden mit dem Vorschlag'],
         ['reich','*an + Dat','reich an Erfahrung']],
   cap:{en:'the B2 exam list — learn them as three-word blocks',fa:'فهرست B2 — به‌صورت بلوک سه‌کلمه‌ای یاد بگیر'}},
  {type:'table',head:['Case it governs','Adjectives','Example'],
   rows:[['*Genitiv','bewusst, sicher, würdig, verdächtig','*Ich war mir des Risikos nicht bewusst.'],
         ['*Dativ','ähnlich, treu, dankbar, klar, peinlich, überlegen, gewachsen','*Dieser Fall ist dem letzten sehr ähnlich.'],
         ['*Akkusativ','wert, gewohnt, los; and measurements','*Das ist einen Versuch wert. / Er ist zwei Meter groß.']],
   cap:{en:'adjectives that need no preposition at all',fa:'صفت‌هایی که هیچ حرف اضافه‌ای نمی‌خواهند'}},
  {type:'examples',items:[
   {de:'Wir sind mit dem Ergebnis sehr zufrieden.',en:'We are very satisfied with the result.',say:'Wir sind mit dem Ergebnis sehr zufrieden.'},
   {de:'Für den Fehler ist die Abteilungsleitung verantwortlich.',en:'The department management is responsible for the error.',say:'Für den Fehler ist die Abteilungsleitung verantwortlich.'},
   {de:'An einer langfristigen Zusammenarbeit sind wir sehr interessiert.',en:'We are very interested in a long-term cooperation.',say:'An einer langfristigen Zusammenarbeit sind wir sehr interessiert.'},
   {de:'Ich war mir der Konsequenzen nicht bewusst.',en:'I was not aware of the consequences.',say:'Ich war mir der Konsequenzen nicht bewusst.'},
   {de:'Das Angebot ist einen Versuch wert.',en:'The offer is worth a try.',say:'Das Angebot ist einen Versuch wert.'},
   {de:'Sie ist stolz darauf, die Prüfung bestanden zu haben.',en:'She is proud of having passed the exam.',say:'Sie ist stolz darauf, die Prüfung bestanden zu haben.'}]},
  {type:'rule',md:{en:'An adjective with a preposition takes the same <b>da-/wo-</b> machinery as a verb: <b>stolz darauf, dass …</b> · <b>zufrieden damit, dass …</b> · <b>überzeugt davon, dass …</b> · <b>Worauf bist du stolz?</b> The correlate always mirrors the adjective\'s own preposition.',
        fa:'صفت با حرف اضافه همان نظام <b>da-/wo-</b> فعل‌ها را دارد: <b>stolz darauf, dass …</b>، <b>überzeugt davon, dass …</b>، <b>Worauf bist du stolz?</b>'}},
  {type:'contrast',cols:[
   {t:'sich interessieren für + Akk',md:{en:'„Ich <b>interessiere mich für</b> Politik."<br>A reflexive <b>verb</b>. This is the everyday way to say what you are into.'}},
   {t:'interessiert sein an + Dat',md:{en:'„Wir <b>sind</b> <b>an</b> einer Zusammenarbeit <b>interessiert</b>."<br>An <b>adjective</b> with a different preposition and a different case. Business register. Same English word, two German patterns — do not blend them into <i>interessiert für</i>.'}}]},
  {type:'warn',md:{en:'Every error here is an English preposition in German clothes: <i>stolz von / über</i> ✗ → <b>stolz auf</b>; <i>interessiert in</i> ✗ → <b>interessiert an</b>; <i>verantwortlich von</i> ✗ → <b>verantwortlich für</b>; <i>abhängig auf</i> ✗ → <b>abhängig von</b>; <i>zufrieden über</i> ✗ → <b>zufrieden mit</b>. And watch the two reflexive pronouns German insists on: <b>Ich bin <i>mir</i> dessen bewusst</b>, <b>Ich bin <i>mir</i> sicher</b>.',
        fa:'هر خطا در اینجا حرف اضافهٔ انگلیسی در لباس آلمانی است: <b>stolz auf</b>، <b>interessiert an</b>، <b>verantwortlich für</b>، <b>abhängig von</b>، <b>zufrieden mit</b>. و ضمیر بازتابی را فراموش نکن: <b>Ich bin mir dessen bewusst.</b>'}},
  {type:'tip',md:{en:'Never learn the adjective alone. Store a whole collocation with a real object: <i>stolz auf meine Arbeit</i>, <i>zufrieden mit der Note</i>, <i>abhängig vom Wetter</i>. The preposition then comes back attached, and the case comes back with the preposition.',
        fa:'صفت را تنها یاد نگیر. کل همنشینی را با یک مفعول واقعی حفظ کن — حرف اضافه و حالت با هم برمی‌گردند.'}},
  {type:'quiz',q:{en:'„Wir sind ___ dem Vorschlag einverstanden."'},
   a:'mit',o:['für','zu','an'],
   ex:{en:'<i>einverstanden</i> governs <b>mit + Dativ</b> — like <i>zufrieden</i>. English „agree <b>to/with</b>" is no guide; the adjective carries its own preposition.'}}
 ]}

];

/* ╔════════════════════════════════════════════════════════╗
   ║  DRILLS — 8 per lesson, keyed by lesson id             ║
   ╚════════════════════════════════════════════════════════╝ */

window.DRILL_B2=[

/* ---- 1 · konjunktiv2-vergangenheit ---- */
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Wenn ich das früher gewusst hätte, ___ ich nichts gesagt.',a:'hätte',o:['wäre','würde','hatte'],ex:'sagen takes haben in the Perfekt, so the unreal past is hätte + gesagt. There is no würde in this tense.',tr:'If I had known that earlier, I would not have said anything.',say:'Wenn ich das früher gewusst hätte, hätte ich nichts gesagt.'},
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Beinahe ___ wir den Auftrag verloren.',a:'hätten',o:['wären','haben','würden'],ex:'beinahe / fast + past Konjunktiv II = it very nearly happened. verlieren takes haben, so: hätten verloren.',tr:'We very nearly lost the contract.',say:'Beinahe hätten wir den Auftrag verloren.'},
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Mit einem früheren Zug ___ ich pünktlich angekommen.',a:'wäre',o:['hätte','würde','war'],ex:'ankommen takes sein in the Perfekt (ich bin angekommen), so the unreal past keeps sein: wäre angekommen.',tr:'With an earlier train I would have arrived on time.',say:'Mit einem früheren Zug wäre ich pünktlich angekommen.'},
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Hätte ich doch den Vertrag genauer ___!',a:'gelesen',o:['lesen','zu lesen','las'],ex:'A verb-first clause with doch is a bare wish about the past: hätte + Partizip II. The participle of lesen is gelesen.',tr:'If only I had read the contract more carefully!',say:'Hätte ich doch den Vertrag genauer gelesen!'},
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Sie ___ den Fehler früher bemerken können.',a:'hätte',o:['wäre','würde','hat'],ex:'With a modal in the past subjunctive the auxiliary is always hätte, followed by the double infinitive bemerken können.',tr:'She could have noticed the mistake earlier.',say:'Sie hätte den Fehler früher bemerken können.'},
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Ich hätte gestern länger arbeiten ___.',a:'müssen',o:['gemusst','müsste','zu müssen'],ex:'A modal that governs a second verb never appears as a participle: hätte arbeiten müssen, not gemusst.',tr:'I would have had to work longer yesterday.',say:'Ich hätte gestern länger arbeiten müssen.'},
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Ohne die Verspätung ___ wir die Konferenz nicht verpasst.',a:'hätten',o:['wären','würden','hatten'],ex:'An ohne-phrase can replace a whole wenn-clause; the main clause still needs the past Konjunktiv II: hätten verpasst.',tr:'Without the delay we would not have missed the conference.',say:'Ohne die Verspätung hätten wir die Konferenz nicht verpasst.'},
{gid:'konjunktiv2-vergangenheit',lv:5,sk:'Konjunktiv',s:'Er ärgert sich, dass er die Stelle ___ bekommen können.',a:'hätte',o:['haben','gehabt','hätte haben'],ex:'In a subordinate clause the finite verb cannot stand behind a double infinitive, so hätte moves in front of bekommen können.',tr:'He is annoyed that he could have got the job.',say:'Er ärgert sich, dass er die Stelle hätte bekommen können.'},

/* ---- 2 · irreale-vergleiche ---- */
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Er tut so, als ___ er alles wüsste.',a:'ob',o:['wie','dass','wann'],ex:'An unreal comparison uses als ob (or als wenn) with the verb at the end. German never uses wie for this.',tr:'He acts as if he knew everything.',say:'Er tut so, als ob er alles wüsste.'},
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Er tut so, als ___ er alles.',a:'wüsste',o:['weiß','wissen','gewusst'],ex:'Drop ob and the finite verb moves up directly behind als — and it stands in Konjunktiv II: als wüsste er alles.',tr:'He acts as if he knew everything.',say:'Er tut so, als wüsste er alles.'},
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Sie sprach über das Projekt, als ob sie es selbst geleitet ___.',a:'hätte',o:['wäre','hat','hatte'],ex:'For a comparison with an earlier event you need the past Konjunktiv II; leiten takes haben, so hätte geleitet.',tr:'She talked about the project as if she had run it herself.',say:'Sie sprach über das Projekt, als ob sie es selbst geleitet hätte.'},
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Nach der Kritik arbeitete er weiter, als ___ nichts geschehen.',a:'wäre',o:['hätte','war','ob'],ex:'geschehen takes sein, so the past Konjunktiv II is wäre geschehen — and after a bare als the verb comes first.',tr:'After the criticism he carried on working as if nothing had happened.',say:'Nach der Kritik arbeitete er weiter, als wäre nichts geschehen.'},
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Es sieht so aus, als ___ die Verhandlungen scheitern.',a:'würden',o:['werden','wären','hätten'],ex:'würde + Infinitiv is the normal Konjunktiv II for ordinary verbs, and after bare als the finite verb leads: als würden die Verhandlungen scheitern.',tr:'It looks as if the negotiations are going to fail.',say:'Es sieht so aus, als würden die Verhandlungen scheitern.'},
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Du redest, ___ du mein Vorgesetzter wärst.',a:'als wenn',o:['als dass','so dass','wie dass'],ex:'als wenn is the spoken twin of als ob: subordinator, verb (wärst) at the end.',tr:'You talk as if you were my superior.',say:'Du redest, als wenn du mein Vorgesetzter wärst.'},
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Er tat so, als ob er den Bericht nicht lesen ___.',a:'könnte',o:['kann','gekonnt','können'],ex:'The modal is the finite verb of the als-ob clause, so it goes last and stands in Konjunktiv II: könnte.',tr:'He acted as if he could not read the report.',say:'Er tat so, als ob er den Bericht nicht lesen könnte.'},
{gid:'irreale-vergleiche',lv:5,sk:'Konjunktiv',s:'Mir ist, als ___ ich diesen Namen schon gehört.',a:'hätte',o:['wäre','habe','würde'],ex:'Mir ist, als … is a fixed frame for a vague impression; hören takes haben, so the past form is hätte gehört.',tr:'I have the feeling I have heard that name before.',say:'Mir ist, als hätte ich diesen Namen schon gehört.'},

/* ---- 3 · passiv-zeiten ---- */
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'Der Antrag ist gestern ___ worden.',a:'genehmigt',o:['genehmigen','zu genehmigen','genehmigte'],ex:'Perfekt passive = sein + Partizip II + worden. The participle of genehmigen is genehmigt.',tr:'The application was approved yesterday.',say:'Der Antrag ist gestern genehmigt worden.'},
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'Die Unterlagen sind vollständig geprüft ___.',a:'worden',o:['geworden','werden','gewesen'],ex:'In the passive, the participle of werden loses its ge-: worden. geworden belongs to werden meaning "to become".',tr:'The documents have been checked in full.',say:'Die Unterlagen sind vollständig geprüft worden.'},
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'Mir ___ bei der Bewerbung sehr geholfen.',a:'wurde',o:['wurden','war','habe'],ex:'helfen takes the Dative, so its passive has no subject at all: the verb stays singular — mir wurde geholfen.',tr:'I was given a lot of help with the application.',say:'Mir wurde bei der Bewerbung sehr geholfen.'},
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'Der Vertrag muss bis Freitag ___ werden.',a:'unterschrieben',o:['unterschreiben','unterschrieb','zu unterschreiben'],ex:'Modal + passive = Partizip II + werden at the end of the sentence: muss unterschrieben werden.',tr:'The contract has to be signed by Friday.',say:'Der Vertrag muss bis Freitag unterschrieben werden.'},
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'Als wir einzogen, ___ das Gebäude schon verkauft worden.',a:'war',o:['hatte','ist','wurde'],ex:'An event before another past event needs the Plusquamperfekt passive: war + Partizip II + worden.',tr:'When we moved in, the building had already been sold.',say:'Als wir einzogen, war das Gebäude schon verkauft worden.'},
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'Die Ergebnisse werden morgen ___ werden.',a:'veröffentlicht',o:['veröffentlichen','veröffentlicht worden','zu veröffentlichen'],ex:'Futur I passive = werden + Partizip II + werden. veröffentlicht worden would make it Futur II.',tr:'The results will be published tomorrow.',say:'Die Ergebnisse werden morgen veröffentlicht werden.'},
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'___ wird hier nicht geraucht.',a:'Es',o:['Man','Das','Dem'],ex:'A subjectless passive still needs the front slot filled, and the placeholder is es. man would require an active sentence: Man raucht hier nicht.',tr:'There is no smoking here.',say:'Es wird hier nicht geraucht.'},
{gid:'passiv-zeiten',lv:5,sk:'Passive',s:'Der Fehler hätte früher ___ werden können.',a:'bemerkt',o:['bemerken','bemerkt worden','zu bemerken'],ex:'Modal + passive in the past subjunctive: hätte + Partizip II + werden + modal infinitive.',tr:'The mistake could have been noticed earlier.',say:'Der Fehler hätte früher bemerkt werden können.'},

/* ---- 4 · infinitiv-advanced ---- */
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'Er verließ die Sitzung, ohne sich ___.',a:'zu verabschieden',o:['verabschieden','verabschiedet','verabschiedete'],ex:'One subject for both actions, so the clause is an infinitive with zu — and ohne always needs that zu.',tr:'He left the meeting without saying goodbye.',say:'Er verließ die Sitzung, ohne sich zu verabschieden.'},
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'Anstatt zu ___, schrieb sie eine E-Mail.',a:'telefonieren',o:['telefoniert','telefonierte','telefonierend'],ex:'anstatt … zu + Infinitiv. The infinitive never carries a tense ending.',tr:'Instead of phoning, she wrote an e-mail.',say:'Anstatt zu telefonieren, schrieb sie eine E-Mail.'},
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'___ ich es wusste, wurde der Termin verschoben.',a:'Ohne dass',o:['Ohne zu','Ohne','Anstatt zu'],ex:'The knowing is mine, the postponing is somebody else\'s — two subjects, so you must use ohne dass with a full clause.',tr:'The appointment was moved without my knowing.',say:'Ohne dass ich es wusste, wurde der Termin verschoben.'},
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'Er ging, ohne dass jemand es ___.',a:'merkte',o:['merken','zu merken','gemerkt'],ex:'ohne dass introduces a normal subordinate clause: finite verb at the end, here merkte.',tr:'He left without anyone noticing.',say:'Er ging, ohne dass jemand es merkte.'},
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'Er reiste ab, ohne sich vorher ___.',a:'anzumelden',o:['anmelden','zu anmelden','angemeldet'],ex:'With a separable verb the zu goes inside, between prefix and stem: an-zu-melden.',tr:'He left without registering beforehand.',say:'Er reiste ab, ohne sich vorher anzumelden.'},
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'Uns bleibt nichts anderes übrig, außer ___ warten.',a:'zu',o:['um','dass','ohne'],ex:'After a negative "nothing but" phrase German uses außer zu + Infinitiv.',tr:'We have no choice but to wait.',say:'Uns bleibt nichts anderes übrig, außer zu warten.'},
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'Anstatt dass die Firma die Löhne ___, kürzte sie die Stunden.',a:'erhöhte',o:['erhöhen','zu erhöhen','erhöht'],ex:'anstatt dass takes a full clause with the finite verb at the end; the Präteritum matches the main clause.',tr:'Instead of raising wages, the company cut the hours.',say:'Anstatt dass die Firma die Löhne erhöhte, kürzte sie die Stunden.'},
{gid:'infinitiv-advanced',lv:5,sk:'Clauses',s:'Sie unterschrieb den Vertrag, ohne ihn ___ zu haben.',a:'gelesen',o:['lesen','las','zu lesen'],ex:'For an action completed before the main one, use Partizip II + zu haben: ohne ihn gelesen zu haben.',tr:'She signed the contract without having read it.',say:'Sie unterschrieb den Vertrag, ohne ihn gelesen zu haben.'},

/* ---- 5 · konnektoren-b2 ---- */
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Er wollte kündigen, ___ er hatte noch keinen neuen Job.',a:'aber',o:['trotzdem','obwohl','dennoch'],ex:'Subject + verb follow untouched, so slot 0 is needed: aber. trotzdem and dennoch would force inversion, obwohl the verb to the end.',tr:'He wanted to resign, but he did not have a new job yet.',say:'Er wollte kündigen, aber er hatte noch keinen neuen Job.'},
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Die Miete ist hoch, ___ bleiben wir in der Wohnung.',a:'trotzdem',o:['obwohl','weil','sondern'],ex:'The verb bleiben comes straight after the gap, so slot 1 must hold a Konjunktionaladverb: trotzdem.',tr:'The rent is high; we are staying in the flat anyway.',say:'Die Miete ist hoch, trotzdem bleiben wir in der Wohnung.'},
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Das Projekt war teuer, ___ hat es sich gelohnt.',a:'dennoch',o:['obwohl','denn','trotz'],ex:'Inversion again (hat es) → an adverb in position 1. dennoch is the formal twin of trotzdem.',tr:'The project was expensive; nonetheless it paid off.',say:'Das Projekt war teuer, dennoch hat es sich gelohnt.'},
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Wir haben den Termin verschoben, ___ der Kunde krank war.',a:'weil',o:['deshalb','denn','trotzdem'],ex:'The finite verb war stands at the very end, which only a Subjunktion can cause: weil.',tr:'We moved the appointment because the client was ill.',say:'Wir haben den Termin verschoben, weil der Kunde krank war.'},
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Ich nehme das Angebot an, ___ es ist das beste.',a:'denn',o:['weil','deshalb','obwohl'],ex:'Main-clause order follows (es ist), so you need the position-0 conjunction denn. weil would send ist to the end.',tr:'I am accepting the offer, because it is the best one.',say:'Ich nehme das Angebot an, denn es ist das beste.'},
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Die Zahlen sind gut; das Risiko ist ___ erheblich.',a:'allerdings',o:['obwohl','denn','sondern'],ex:'allerdings can sit inside the middle field without touching the word order — a quieter, more written kind of contrast.',tr:'The figures are good; the risk, however, is considerable.',say:'Die Zahlen sind gut; das Risiko ist allerdings erheblich.'},
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Er ist ___ qualifiziert, aber völlig unerfahren.',a:'zwar',o:['obwohl','sondern','weil'],ex:'zwar … aber is a correlative frame: zwar concedes the first half, aber carries the real point.',tr:'He is qualified, admittedly, but completely inexperienced.',say:'Er ist zwar qualifiziert, aber völlig unerfahren.'},
{gid:'konnektoren-b2',lv:5,sk:'Connectors',s:'Wir investieren mehr, ___ die Qualität steigen kann.',a:'damit',o:['um','deshalb','dafür'],ex:'A purpose clause with its own subject and a finite verb at the end needs damit. um would require um … zu + Infinitiv and the same subject.',tr:'We are investing more so that quality can rise.',say:'Wir investieren mehr, damit die Qualität steigen kann.'},

/* ---- 6 · praepositional-objekt ---- */
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'Ich warte seit zwei Wochen ___ eine Antwort.',a:'auf',o:['für','nach','an'],ex:'warten governs auf + Akkusativ. English "wait for" is no guide at all.',tr:'I have been waiting for an answer for two weeks.',say:'Ich warte seit zwei Wochen auf eine Antwort.'},
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'Ich habe mich ___ das Lob meines Chefs sehr gefreut.',a:'über',o:['für','von','an'],ex:'sich freuen über + Akkusativ = pleased about something that has happened. sich freuen auf would point to something still ahead.',tr:'I was very pleased about my boss\'s praise.',say:'Ich habe mich über das Lob meines Chefs sehr gefreut.'},
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'Die Prüfung besteht ___ drei Teilen.',a:'aus',o:['auf','in','von'],ex:'bestehen aus + Dativ = to consist of. bestehen auf + Dativ would mean "to insist on" — the preposition is the meaning.',tr:'The exam consists of three parts.',say:'Die Prüfung besteht aus drei Teilen.'},
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'Ich kann mich ___ nicht erinnern.',a:'daran',o:['damit','darauf','dazu'],ex:'sich erinnern an → the da-form mirrors the verb\'s own preposition: daran. The -r- appears because an begins with a vowel.',tr:'I cannot remember that.',say:'Ich kann mich daran nicht erinnern.'},
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'___ beschäftigt sich die Studie?',a:'Womit',o:['Wofür','Worauf','Mit was'],ex:'sich beschäftigen mit → the question word for a thing is wo- + preposition: womit. Mit was is colloquial only.',tr:'What does the study deal with?',say:'Womit beschäftigt sich die Studie?'},
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'Alles hängt ___ ab, ob die Finanzierung steht.',a:'davon',o:['daran','darauf','dazu'],ex:'abhängen von → davon, here pointing forward to the ob-clause that follows.',tr:'Everything depends on whether the funding is in place.',say:'Alles hängt davon ab, ob die Finanzierung steht.'},
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'Wir müssen damit rechnen, ___ die Kosten steigen.',a:'dass',o:['ob','wenn','was'],ex:'The correlate damit announces the content, which arrives as a dass-clause with the verb at the end.',tr:'We have to reckon with costs rising.',say:'Wir müssen damit rechnen, dass die Kosten steigen.'},
{gid:'praepositional-objekt',lv:5,sk:'Prepositions',s:'Die Gewerkschaft beharrt ___, dass die Löhne steigen.',a:'darauf',o:['davon','daran','dazu'],ex:'beharren auf → darauf. Look up the verb, not the meaning: the correlate always copies the verb\'s preposition.',tr:'The union insists that wages be raised.',say:'Die Gewerkschaft beharrt darauf, dass die Löhne steigen.'},

/* ---- 7 · wortstellung-fokus ---- */
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'Ich habe ___ gestern geschickt.',a:'es ihm',o:['ihm es','ihn ihm','ihm ihn'],ex:'Two pronouns: Akkusativ before Dativ — es ihm. With nouns the order would be the other way round.',tr:'I sent it to him yesterday.',say:'Ich habe es ihm gestern geschickt.'},
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'Ich schicke morgen ___ die Unterlagen.',a:'dem Kunden',o:['den Kunden','der Kunde','dem Kunde'],ex:'Two nouns: Dativ before Akkusativ. Kunde is an n-declension noun, so the Dative is dem Kunden.',tr:'I will send the client the documents tomorrow.',say:'Ich schicke morgen dem Kunden die Unterlagen.'},
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'Gestern hat ___ der Chef vor allen gelobt.',a:'mich',o:['mir','ich','meiner'],ex:'loben takes the Akkusativ, and a pronoun object slips in front of the noun subject right after the finite verb.',tr:'Yesterday the boss praised me in front of everyone.',say:'Gestern hat mich der Chef vor allen gelobt.'},
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'Sie ist ___ wegen des Streiks mit dem Bus zur Arbeit gefahren.',a:'heute',o:['zur Arbeit','mit dem Auto','sehr'],ex:'Kausal, Modal and Lokal are already there, so only the temporal slot is free — and TeKaMoLo puts it first.',tr:'Today she went to work by bus because of the strike.',say:'Sie ist heute wegen des Streiks mit dem Bus zur Arbeit gefahren.'},
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'Die Zahl der Bewerbungen ist stärker gestiegen ___ im Vorjahr.',a:'als',o:['wie','denn','dass'],ex:'Comparisons stay outside the verb bracket (Ausklammerung) — and after a comparative German uses als, never wie.',tr:'The number of applications has risen more sharply than last year.',say:'Die Zahl der Bewerbungen ist stärker gestiegen als im Vorjahr.'},
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'___ habe ich den Antrag eingereicht.',a:'Letzte Woche',o:['Letzte Woche ich','Ich letzte Woche','Den Antrag letzte Woche'],ex:'The Vorfeld holds exactly one element. Two elements in front of the finite verb is the hardest word-order error to unlearn.',tr:'Last week I submitted the application.',say:'Letzte Woche habe ich den Antrag eingereicht.'},
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'Deshalb hat ___ der Vorstand nicht informiert.',a:'uns',o:['wir','unser','unsere'],ex:'informieren takes the Akkusativ (uns), and the pronoun object comes before the noun subject in the middle field.',tr:'That is why the board did not inform us.',say:'Deshalb hat uns der Vorstand nicht informiert.'},
{gid:'wortstellung-fokus',lv:5,sk:'Sentences',s:'Dem Antragsteller ___ die Unterlagen bereits zugeschickt.',a:'wurden',o:['wurde','worden','geworden'],ex:'The Dative object sits in the Vorfeld, but the subject is still die Unterlagen (plural) — so the passive verb is wurden.',tr:'The documents had already been sent to the applicant.',say:'Dem Antragsteller wurden die Unterlagen bereits zugeschickt.'},

/* ---- 8 · nominalisierung-b2 ---- */
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'___ des schlechten Wetters wurde der Flug gestrichen.',a:'Wegen',o:['Weil','Denn','Da'],ex:'A noun phrase in the Genitive follows, so you need a preposition: wegen. weil, denn and da all require a clause with a verb.',tr:'Because of the bad weather the flight was cancelled.',say:'Wegen des schlechten Wetters wurde der Flug gestrichen.'},
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'Trotz ___ Kritik hielt die Ministerin an dem Plan fest.',a:'heftiger',o:['heftige','heftigen','heftigem'],ex:'trotz takes the Genitive; with no article the feminine singular adjective carries the strong ending -er: trotz heftiger Kritik.',tr:'Despite fierce criticism the minister stuck to the plan.',say:'Trotz heftiger Kritik hielt die Ministerin an dem Plan fest.'},
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'___ Abschluss des Studiums arbeitete sie im Ausland.',a:'Nach',o:['Nachdem','Bevor','Seitdem'],ex:'nachdem + clause becomes nach + noun. The conjunctions in the options would all need a finite verb at the end.',tr:'After finishing her degree she worked abroad.',say:'Nach Abschluss des Studiums arbeitete sie im Ausland.'},
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'___ Steigerung der Effizienz wurden neue Geräte angeschafft.',a:'Zur',o:['Zum','Damit','Um die'],ex:'Purpose in nominal style = zu + Dativ, and die Steigerung is feminine: zu der → zur.',tr:'New devices were purchased in order to increase efficiency.',say:'Zur Steigerung der Effizienz wurden neue Geräte angeschafft.'},
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'Die Kosten wurden ___ den Abbau von Stellen gesenkt.',a:'durch',o:['indem','von','aus'],ex:'indem (means, method) becomes durch + Akkusativ. von would name an agent, not a method.',tr:'Costs were cut by reducing the number of posts.',say:'Die Kosten wurden durch den Abbau von Stellen gesenkt.'},
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'Der Anspruch erlischt, ___ nicht gezahlt wird.',a:'wenn',o:['bei','ob','dass'],ex:'The reverse direction: bei Nichtzahlung unfolds into a condition clause with wenn and the verb at the end.',tr:'The claim lapses if no payment is made.',say:'Der Anspruch erlischt, wenn nicht gezahlt wird.'},
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'___ er viel Erfahrung hatte, bekam er die Stelle nicht.',a:'Obwohl',o:['Trotz','Trotzdem','Dennoch'],ex:'trotz seiner Erfahrung unfolds into the subordinator obwohl with the verb at the end. trotzdem and dennoch are adverbs.',tr:'Although he had a lot of experience, he did not get the job.',say:'Obwohl er viel Erfahrung hatte, bekam er die Stelle nicht.'},
{gid:'nominalisierung-b2',lv:5,sk:'Style',s:'Aufgrund ___ Datenlage kann die Studie nichts beweisen.',a:'der dünnen',o:['die dünne','den dünnen','der dünne'],ex:'aufgrund takes the Genitive; feminine Genitive is der, and after an article the adjective takes the weak ending -en.',tr:'Because of the thin data the study cannot prove anything.',say:'Aufgrund der dünnen Datenlage kann die Studie nichts beweisen.'},

/* ---- 9 · attribut-typen ---- */
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Die ___ Unterlagen liegen im Sekretariat.',a:'unterschriebenen',o:['unterschrieben','unterschreibenden','unterschreiben'],ex:'A Partizip II attribute is passive and completed, and it must be declined like any adjective: die unterschriebenen Unterlagen.',tr:'The signed documents are in the office.',say:'Die unterschriebenen Unterlagen liegen im Sekretariat.'},
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Die ___ Zahl der Bewerbungen freut die Personalabteilung.',a:'steigende',o:['steigend','steigenden','zu steigende'],ex:'Partizip I (Infinitiv + d) is active and simultaneous: die Zahl, die steigt → die steigende Zahl, nominative feminine ending -e.',tr:'The rising number of applications pleases the HR department.',say:'Die steigende Zahl der Bewerbungen freut die Personalabteilung.'},
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Der Vorsitzende ___ erklärte den Beschluss.',a:'des Ausschusses',o:['dem Ausschuss','der Ausschuss','den Ausschuss'],ex:'A Genitivattribut answers "of what?": der Vorsitzende des Ausschusses.',tr:'The chair of the committee explained the decision.',say:'Der Vorsitzende des Ausschusses erklärte den Beschluss.'},
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Der Kollege, ___ ich den Bericht geschickt habe, antwortet nicht.',a:'dem',o:['den','der','dessen'],ex:'schicken gives the person in the Dative, so the relative pronoun for masculine singular is dem.',tr:'The colleague I sent the report to is not replying.',say:'Der Kollege, dem ich den Bericht geschickt habe, antwortet nicht.'},
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Wir sprachen mit Frau Weber, ___ Leiterin der Abteilung.',a:'der',o:['die','den','dem'],ex:'An apposition copies the case of the noun it explains: mit + Dativ → der Leiterin.',tr:'We spoke with Ms Weber, the head of the department.',say:'Wir sprachen mit Frau Weber, der Leiterin der Abteilung.'},
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Die Nachfrage ___ Elektroautos ist deutlich gewachsen.',a:'nach',o:['für','auf','über'],ex:'A prepositional attribute keeps the preposition of the underlying word: nachfragen / die Nachfrage nach + Dativ.',tr:'Demand for electric cars has grown markedly.',say:'Die Nachfrage nach Elektroautos ist deutlich gewachsen.'},
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Das ___ Gesetz tritt im Januar in Kraft.',a:'vom Bundestag beschlossene',o:['vom Bundestag beschlossen','beschlossene vom Bundestag','vom Bundestag beschlossenen'],ex:'The whole extended participial phrase sits between article and noun, and the participle takes the ending of the noun phrase: das … beschlossene Gesetz.',tr:'The law passed by parliament comes into force in January.',say:'Das vom Bundestag beschlossene Gesetz tritt im Januar in Kraft.'},
{gid:'attribut-typen',lv:5,sk:'Adjectives',s:'Der Bericht, ___ Zahlen veraltet sind, wurde zurückgezogen.',a:'dessen',o:['deren','den','der'],ex:'A Genitive attribute inside a relative clause: the figures belong to der Bericht (masculine), so dessen.',tr:'The report, whose figures are out of date, was withdrawn.',say:'Der Bericht, dessen Zahlen veraltet sind, wurde zurückgezogen.'},

/* ---- 10 · modalverben-perfekt ---- */
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Ich habe gestern bis acht ___ müssen.',a:'arbeiten',o:['gearbeitet','zu arbeiten','arbeitete'],ex:'Double infinitive: haben + full-verb infinitive + modal infinitive. Neither verb takes a participle form.',tr:'I had to work until eight yesterday.',say:'Ich habe gestern bis acht arbeiten müssen.'},
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Sie hat den Zug nicht mehr erreichen ___.',a:'können',o:['gekonnt','konnte','zu können'],ex:'A modal that governs a second verb stays an infinitive and comes last: erreichen können.',tr:'She was no longer able to catch the train.',say:'Sie hat den Zug nicht mehr erreichen können.'},
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Das habe ich wirklich nicht ___.',a:'gewollt',o:['wollen','wollte','zu wollen'],ex:'Here wollen has no second verb, so it behaves like a normal verb and forms a real participle: gewollt.',tr:'I really did not intend that.',say:'Das habe ich wirklich nicht gewollt.'},
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Er ___ nach Berlin fahren müssen.',a:'hat',o:['ist','war','wird'],ex:'Modal constructions always take haben, even when the full verb (fahren) would normally take sein.',tr:'He had to go to Berlin.',say:'Er hat nach Berlin fahren müssen.'},
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Ich weiß, dass sie das Angebot nicht ___ ablehnen können.',a:'hat',o:['haben','gehabt','hat gehabt'],ex:'In a subordinate clause the finite verb moves in front of the double infinitive: dass sie … hat ablehnen können.',tr:'I know that she was unable to turn the offer down.',say:'Ich weiß, dass sie das Angebot nicht hat ablehnen können.'},
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Ich habe mir die Haare schneiden ___.',a:'lassen',o:['gelassen','lässt','zu lassen'],ex:'lassen follows the modal pattern exactly: haben + Infinitiv + lassen, never gelassen when a second verb is present.',tr:'I had my hair cut.',say:'Ich habe mir die Haare schneiden lassen.'},
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Ich habe das Telefon nicht klingeln ___.',a:'hören',o:['zu hören','höre','hörend'],ex:'hören and sehen take a bare infinitive and form the Perfekt as a double infinitive: klingeln hören.',tr:'I did not hear the phone ring.',say:'Ich habe das Telefon nicht klingeln hören.'},
{gid:'modalverben-perfekt',lv:5,sk:'Verbs',s:'Sie ___ den Termin verschieben können, wenn sie früher angerufen hätte.',a:'hätte',o:['wäre','würde','hat'],ex:'The unreal past of a modal construction: hätte + Infinitiv + modal infinitive — hätte verschieben können.',tr:'She could have postponed the appointment if she had called earlier.',say:'Sie hätte den Termin verschieben können, wenn sie früher angerufen hätte.'},

/* ---- 11 · verbgefuege ---- */
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Ich ___ mir morgen die Haare schneiden.',a:'lasse',o:['habe','werde','mache'],ex:'lassen + Infinitiv = to have something done by somebody else. The Dative mir says who it is done for.',tr:'I am having my hair cut tomorrow.',say:'Ich lasse mir morgen die Haare schneiden.'},
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Das Problem ___ sich leicht lösen.',a:'lässt',o:['lasst','kann','wird'],ex:'sich lassen + Infinitiv is a passive substitute: lässt sich lösen = kann gelöst werden.',tr:'The problem can easily be solved.',say:'Das Problem lässt sich leicht lösen.'},
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Bitte ___ Sie sitzen!',a:'bleiben',o:['bleibt','geblieben','sind'],ex:'bleiben + bare infinitive describes staying in a position: sitzen bleiben, stehen bleiben, liegen bleiben.',tr:'Please stay seated.',say:'Bitte bleiben Sie sitzen!'},
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Wir gehen nach der Arbeit noch ___.',a:'einkaufen',o:['zu einkaufen','eingekauft','einkaufend'],ex:'gehen + bare infinitive = to go and do something. No zu, no comma.',tr:'We are going shopping after work.',say:'Wir gehen nach der Arbeit noch einkaufen.'},
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Ich habe ihn im Flur ___ hören.',a:'telefonieren',o:['zu telefonieren','telefoniert','telefonierend'],ex:'hören takes an accusative object plus a bare infinitive, and in the Perfekt you get the double infinitive telefonieren hören.',tr:'I heard him on the phone in the corridor.',say:'Ich habe ihn im Flur telefonieren hören.'},
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Ich habe meinen Laptop im Büro ___ lassen.',a:'liegen',o:['gelegt','legen','liegt'],ex:'liegen lassen = to leave something behind. The position verb stays an infinitive in this fixed combination.',tr:'I left my laptop at the office.',say:'Ich habe meinen Laptop im Büro liegen lassen.'},
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Sie kommt uns morgen ___.',a:'besuchen',o:['zu besuchen','besucht','besuchend'],ex:'kommen + bare infinitive = to come and do something: Sie kommt uns besuchen.',tr:'She is coming to visit us tomorrow.',say:'Sie kommt uns morgen besuchen.'},
{gid:'verbgefuege',lv:5,sk:'Verbs',s:'Der Schaden hätte sich ___ lassen.',a:'vermeiden',o:['vermieden','zu vermeiden','vermeidet'],ex:'sich lassen in the unreal past: hätte sich vermeiden lassen = hätte vermieden werden können.',tr:'The damage could have been avoided.',say:'Der Schaden hätte sich vermeiden lassen.'},

/* ---- 12 · korrelat ---- */
{gid:'korrelat',lv:5,sk:'Sentences',s:'___ freut mich, dass Sie zusagen.',a:'Es',o:['Er','Ihn','Dem'],ex:'The real subject is the dass-clause, which comes later — so the placeholder es fills the front slot.',tr:'I am glad that you are accepting.',say:'Es freut mich, dass Sie zusagen.'},
{gid:'korrelat',lv:5,sk:'Sentences',s:'Ich finde ___ gut, dass das Thema offen diskutiert wird.',a:'es',o:['ihn','dem','sich'],ex:'finden + adjective always needs the correlate es: Ich finde es gut/wichtig/schade, dass …',tr:'I think it is good that the topic is being discussed openly.',say:'Ich finde es gut, dass das Thema offen diskutiert wird.'},
{gid:'korrelat',lv:5,sk:'Sentences',s:'Ich hoffe, ___ der Termin bleibt.',a:'dass',o:['es dass','ob dass','damit'],ex:'hoffen takes a plain dass-object and no correlate. Ich hoffe es, dass … is the classic B2 over-correction.',tr:'I hope the appointment stands.',say:'Ich hoffe, dass der Termin bleibt.'},
{gid:'korrelat',lv:5,sk:'Sentences',s:'Wir halten ___ für sinnvoll, die Frist zu verlängern.',a:'es',o:['sich','ihn','dafür'],ex:'halten für + adjective is an adjective complement, so the correlate es is obligatory.',tr:'We consider it sensible to extend the deadline.',say:'Wir halten es für sinnvoll, die Frist zu verlängern.'},
{gid:'korrelat',lv:5,sk:'Sentences',s:'Dass die Preise steigen, ___ niemanden.',a:'überrascht',o:['es überrascht','überrascht es','überraschen'],ex:'Once the clause stands in the Vorfeld it IS the subject, so no es is left: the finite verb follows immediately.',tr:'That prices are rising surprises nobody.',say:'Dass die Preise steigen, überrascht niemanden.'},
{gid:'korrelat',lv:5,sk:'Sentences',s:'Wir rechnen ___, dass die Kosten steigen.',a:'damit',o:['es','darauf','davon'],ex:'A verb with a prepositional object takes a da-form, never es: rechnen mit → damit, dass …',tr:'We are reckoning with costs rising.',say:'Wir rechnen damit, dass die Kosten steigen.'},
{gid:'korrelat',lv:5,sk:'Sentences',s:'Es ist wichtig, ___ alle Mitarbeiter informiert werden.',a:'dass',o:['damit','ob','zu'],ex:'es ist + Adjektiv announces a dass-clause. damit would express purpose, which is not what this sentence says.',tr:'It is important that all employees are informed.',say:'Es ist wichtig, dass alle Mitarbeiter informiert werden.'},
{gid:'korrelat',lv:5,sk:'Sentences',s:'Mir ___ nicht aufgefallen, dass die Zahlen fehlen.',a:'ist',o:['hat','habe','wurde'],ex:'auffallen takes sein in the Perfekt, and because mir already occupies the Vorfeld no es is needed.',tr:'I did not notice that the figures were missing.',say:'Mir ist nicht aufgefallen, dass die Zahlen fehlen.'},

/* ---- 13 · konzessiv-b2 ---- */
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'___ es stark regnete, fand das Fest statt.',a:'Obwohl',o:['Trotzdem','Trotz','Dennoch'],ex:'The verb regnete stands at the end of the first clause, so the slot needs a Subjunktion: obwohl.',tr:'Although it was raining hard, the festival took place.',say:'Obwohl es stark regnete, fand das Fest statt.'},
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'Es regnete stark, ___ fand das Fest statt.',a:'dennoch',o:['obwohl','trotz','wenngleich'],ex:'Inversion follows (fand das Fest), so position 1 must hold a concessive adverb: dennoch or trotzdem.',tr:'It was raining hard; the festival took place nonetheless.',say:'Es regnete stark, dennoch fand das Fest statt.'},
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'___ wenn du Recht hast, hilft das jetzt nicht.',a:'Selbst',o:['Obwohl','Trotzdem','Dennoch'],ex:'selbst wenn / auch wenn concedes something merely possible: even if you are right. obwohl would claim it as a fact.',tr:'Even if you are right, that does not help now.',say:'Selbst wenn du Recht hast, hilft das jetzt nicht.'},
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'Das Angebot ist ___ günstig, aber völlig unflexibel.',a:'zwar',o:['obwohl','dennoch','trotz'],ex:'zwar … aber is a frame: zwar grants the first point, aber delivers the one that counts.',tr:'The offer is cheap, admittedly, but totally inflexible.',say:'Das Angebot ist zwar günstig, aber völlig unflexibel.'},
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'Trotz ___ Bedenken wurde das Gesetz verabschiedet.',a:'aller',o:['alle','allen','allem'],ex:'trotz takes the Genitive; the Genitive plural of alle is aller: trotz aller Bedenken.',tr:'Despite all reservations the law was passed.',say:'Trotz aller Bedenken wurde das Gesetz verabschiedet.'},
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'Der Plan ist, ___ er teuer ist, durchaus sinnvoll.',a:'wenngleich',o:['trotzdem','trotz','dennoch'],ex:'wenngleich is a formal Subjunktion — verb at the end — and fits a written register. The options are adverbs or a preposition.',tr:'The plan, expensive though it is, makes good sense.',say:'Der Plan ist, wenngleich er teuer ist, durchaus sinnvoll.'},
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'Auch wenn die Zahlen ___, bleibt das Risiko hoch.',a:'stimmen',o:['stimmt','zu stimmen','gestimmt'],ex:'auch wenn sends the finite verb to the end, and it must agree with the plural subject die Zahlen.',tr:'Even if the figures are right, the risk stays high.',say:'Auch wenn die Zahlen stimmen, bleibt das Risiko hoch.'},
{gid:'konzessiv-b2',lv:5,sk:'Connectors',s:'Ungeachtet ___ Warnungen hielt der Vorstand am Kurs fest.',a:'wiederholter',o:['wiederholte','wiederholten','wiederholtem'],ex:'ungeachtet is a very formal Genitive preposition; with no article the plural adjective takes the strong ending -er.',tr:'Notwithstanding repeated warnings, the board stuck to its course.',say:'Ungeachtet wiederholter Warnungen hielt der Vorstand am Kurs fest.'},

/* ---- 14 · redewiedergabe ---- */
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Die Abgeordneten erklärten, sie ___ dem Gesetz nicht zu.',a:'stimmten',o:['stimmen','gestimmt','stimme'],ex:'Konjunktiv I of the plural (stimmen zu) looks like the Indikativ, so the substitution rule sends you to Konjunktiv II: stimmten zu.',tr:'The MPs stated that they were not voting for the law.',say:'Die Abgeordneten erklärten, sie stimmten dem Gesetz nicht zu.'},
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Er betonte, er ___ nichts von der Absprache gewusst.',a:'habe',o:['hat','hatte','haben'],ex:'Konjunktiv I of haben in the 3rd person singular is habe; with a participle it reports an earlier event.',tr:'He stressed that he had known nothing of the arrangement.',say:'Er betonte, er habe nichts von der Absprache gewusst.'},
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Die Anwälte sagten, die Vorwürfe ___ unbegründet.',a:'seien',o:['sind','seiend','sei'],ex:'sein has a full Konjunktiv I: sei, seist, sei, seien … The plural subject die Vorwürfe needs seien.',tr:'The lawyers said the accusations were unfounded.',say:'Die Anwälte sagten, die Vorwürfe seien unbegründet.'},
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Sie sagte gestern, sie ___ heute im Homeoffice.',a:'sei',o:['war','ist gewesen','werde'],ex:'German does not backshift the tense: a present state stays present in Konjunktiv I — sie sei im Homeoffice.',tr:'She said yesterday that she was working from home today.',say:'Sie sagte gestern, sie sei heute im Homeoffice.'},
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Laut ___ Pressemitteilung steigt der Umsatz.',a:'der',o:['die','den','des'],ex:'laut takes the Dative, and Pressemitteilung is feminine: laut der Pressemitteilung (or simply laut Pressemitteilung).',tr:'According to the press release, turnover is rising.',say:'Laut der Pressemitteilung steigt der Umsatz.'},
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Dem Bericht ___ wurden Daten manipuliert.',a:'zufolge',o:['laut','infolge','aufgrund'],ex:'zufolge follows its noun and takes the Dative: dem Bericht zufolge. laut would have to come first, infolge and aufgrund need a Genitive.',tr:'According to the report, data were manipulated.',say:'Dem Bericht zufolge wurden Daten manipuliert.'},
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Mein Kollege hat erzählt, ___ er den Job wechselt.',a:'dass',o:['ob','sei','wie dass'],ex:'Everyday speech reports with dass + Indikativ. Konjunktiv I here would sound absurdly formal among colleagues.',tr:'My colleague told me that he is changing jobs.',say:'Mein Kollege hat erzählt, dass er den Job wechselt.'},
{gid:'redewiedergabe',lv:5,sk:'Konjunktiv',s:'Der Vorstand teilte mit, die Zahlen ___ noch geprüft.',a:'würden',o:['werden','wurden','seien'],ex:'In a reported passive, Konjunktiv I (werden) would equal the Indikativ, so you substitute Konjunktiv II: würden geprüft.',tr:'The board announced that the figures were still being checked.',say:'Der Vorstand teilte mit, die Zahlen würden noch geprüft.'},

/* ---- 15 · adjektiv-rektion ---- */
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Sie ist sehr stolz ___ ihre Tochter.',a:'auf',o:['von','über','für'],ex:'stolz governs auf + Akkusativ. English "proud of" tempts you into von — a classic B2 slip.',tr:'She is very proud of her daughter.',say:'Sie ist sehr stolz auf ihre Tochter.'},
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Wir sind ___ dem Ergebnis sehr zufrieden.',a:'mit',o:['über','von','an'],ex:'zufrieden governs mit + Dativ — and so does einverstanden.',tr:'We are very satisfied with the result.',say:'Wir sind mit dem Ergebnis sehr zufrieden.'},
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Die Abteilungsleitung ist ___ den Fehler verantwortlich.',a:'für',o:['von','an','über'],ex:'verantwortlich governs für + Akkusativ: verantwortlich für den Fehler.',tr:'The department management is responsible for the error.',say:'Die Abteilungsleitung ist für den Fehler verantwortlich.'},
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Viele Betriebe sind ___ Subventionen abhängig.',a:'von',o:['an','auf','für'],ex:'abhängig governs von + Dativ. English "dependent on" is misleading here.',tr:'Many businesses are dependent on subsidies.',say:'Viele Betriebe sind von Subventionen abhängig.'},
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Dieser Fall ist ___ letzten sehr ähnlich.',a:'dem',o:['den','der','des'],ex:'ähnlich governs the plain Dative, with no preposition at all: dem letzten Fall ähnlich.',tr:'This case is very similar to the last one.',say:'Dieser Fall ist dem letzten sehr ähnlich.'},
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Ich war mir ___ Risikos nicht bewusst.',a:'des',o:['dem','das','der'],ex:'bewusst governs the Genitive, and it needs the reflexive Dative mir: Ich war mir des Risikos bewusst.',tr:'I was not aware of the risk.',say:'Ich war mir des Risikos nicht bewusst.'},
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Sie ist stolz ___, dass sie die Prüfung geschafft hat.',a:'darauf',o:['davon','daran','dazu'],ex:'An adjective with a preposition uses the same da-forms as a verb: stolz auf → stolz darauf, dass …',tr:'She is proud of having passed the exam.',say:'Sie ist stolz darauf, dass sie die Prüfung geschafft hat.'},
{gid:'adjektiv-rektion',lv:5,sk:'Adjectives',s:'Das Angebot ist ___ Versuch wert.',a:'einen',o:['einem','eines','ein'],ex:'wert is one of the few adjectives that governs the Akkusativ: einen Versuch wert, die Mühe wert.',tr:'The offer is worth a try.',say:'Das Angebot ist einen Versuch wert.'}

];
